searchData={"items":[{"type":"module","title":"shigoto","doc":"Public API for the Shigoto background job system.\n\nShigoto (仕事, \"work\") is a PostgreSQL-backed job queue for the Nova ecosystem.\nJobs are claimed via `FOR UPDATE SKIP LOCKED` for safe multi-node operation.","ref":"shigoto.html"},{"type":"module","title":"Quick Start - shigoto","doc":"```erlang\n%% Define a worker\n-module(my_email_worker).\n-behaviour(shigoto_worker).\n-export([perform/1]).\n\nperform(#{<<\\\"to\\\">> := To, <<\\\"subject\\\">> := Subject}) ->\n    send_email(To, Subject),\n    ok.\n```\n\n```erlang\n%% Enqueue a job\nshigoto:insert(#{\n    worker => my_email_worker,\n    args => #{<<\\\"to\\\">> => <<\\\"user@example.com\\\">>, <<\\\"subject\\\">> => <<\\\"Hello\\\">>}\n}).\n```","ref":"shigoto.html#module-quick-start"},{"type":"module","title":"Bulk Insert - shigoto","doc":"```erlang\nshigoto:insert_all([\n    #{worker => my_worker, args => #{<<\\\"id\\\">> => 1}},\n    #{worker => my_worker, args => #{<<\\\"id\\\">> => 2}},\n    #{worker => my_worker, args => #{<<\\\"id\\\">> => 3}}\n]).\n```","ref":"shigoto.html#module-bulk-insert"},{"type":"module","title":"Batches - shigoto","doc":"```erlang\n{ok, Batch} = shigoto:new_batch(#{\n    callback_worker => my_batch_callback,\n    callback_args => #{<<\\\"report\\\">> => 1}\n}),\nBatchId = maps:get(id, Batch),\nshigoto:insert(#{worker => step1, args => #{}, batch => BatchId}),\nshigoto:insert(#{worker => step2, args => #{}, batch => BatchId}).\n```","ref":"shigoto.html#module-batches"},{"type":"module","title":"Transactional Enqueue - shigoto","doc":"Enqueue jobs atomically with your own database writes. Jobs inserted inside\n`transaction/1` commit together with the surrounding work, and are dropped if it\nrolls back — so a job is never orphaned by a failed transaction, nor lost after a\nsuccessful one.\n\n```erlang\nshigoto:transaction(fun() ->\n    {ok, User} = my_app:create_user(Params),\n    {ok, _Job} = shigoto:insert(#{\n        worker => welcome_email_worker,\n        args => #{~\"user_id\" => maps:get(id, User)}\n    }),\n    User\nend).\n```","ref":"shigoto.html#module-transactional-enqueue"},{"type":"function","title":"shigoto.add_queue/2","doc":"Add a queue at runtime without restart.","ref":"shigoto.html#add_queue/2"},{"type":"function","title":"shigoto.cancel/1","doc":"Cancel a job by ID. Stops the job if it is executing on this node.\n\nNot transaction-aware: the process stop and `job_cancelled` telemetry fire\nimmediately, so this always uses the configured pool rather than an enclosing\n`transaction/1,2` pool.","ref":"shigoto.html#cancel/1"},{"type":"function","title":"shigoto.cancel/2","doc":"Cancel a job by ID. Also stops executing jobs on this node.","ref":"shigoto.html#cancel/2"},{"type":"function","title":"shigoto.cancel_by/1","doc":"Cancel jobs matching a pattern. Uses the active transaction's pool, or the configured pool. Filters: worker, queue, tags, args.","ref":"shigoto.html#cancel_by/1"},{"type":"function","title":"shigoto.cancel_by/2","doc":"Cancel jobs matching a pattern. Filters: worker, queue, tags, args.","ref":"shigoto.html#cancel_by/2"},{"type":"function","title":"shigoto.drain_queue/1","doc":"Drain a queue synchronously. Useful for testing.","ref":"shigoto.html#drain_queue/1"},{"type":"function","title":"shigoto.drain_queue/2","doc":"Drain a queue with options (e.g., `#{timeout => 5000}`).","ref":"shigoto.html#drain_queue/2"},{"type":"function","title":"shigoto.get_batch/1","doc":"Get a batch by ID.","ref":"shigoto.html#get_batch/1"},{"type":"function","title":"shigoto.get_job/1","doc":"Get a job by ID.","ref":"shigoto.html#get_job/1"},{"type":"function","title":"shigoto.health/0","doc":"Health check. Returns ok with stats or error with details.","ref":"shigoto.html#health/0"},{"type":"function","title":"shigoto.insert/1","doc":"Insert a job with default options.","ref":"shigoto.html#insert/1"},{"type":"function","title":"shigoto.insert/2","doc":"Insert a job with options. Params: worker, args, queue, priority, scheduled_at, max_attempts, unique, tags, batch.","ref":"shigoto.html#insert/2"},{"type":"function","title":"shigoto.insert_all/1","doc":"Bulk insert multiple jobs with default options.","ref":"shigoto.html#insert_all/1"},{"type":"function","title":"shigoto.insert_all/2","doc":"Bulk insert multiple jobs with options.","ref":"shigoto.html#insert_all/2"},{"type":"function","title":"shigoto.new_batch/1","doc":"Create a new batch for grouping jobs.","ref":"shigoto.html#new_batch/1"},{"type":"function","title":"shigoto.pause_queue/1","doc":"Pause a queue by name — stops claiming new jobs.","ref":"shigoto.html#pause_queue/1"},{"type":"function","title":"shigoto.perform_job/2","doc":"Run a worker through Shigoto's real perform path with no database, for unit\ntests. Returns the raw worker result. See `m:shigoto_testing`.","ref":"shigoto.html#perform_job/2"},{"type":"function","title":"shigoto.perform_job/3","doc":"Like `perform_job/2` with extra job context (`deps_results`, `attempt`, ...).","ref":"shigoto.html#perform_job/3"},{"type":"function","title":"shigoto.remove_queue/1","doc":"Remove a queue at runtime. Waits for in-flight jobs to finish.","ref":"shigoto.html#remove_queue/1"},{"type":"function","title":"shigoto.report_progress/2","doc":"Report job progress (0-100). Call from within a worker's perform/1.","ref":"shigoto.html#report_progress/2"},{"type":"function","title":"shigoto.resume_queue/1","doc":"Resume a paused queue by name.","ref":"shigoto.html#resume_queue/1"},{"type":"function","title":"shigoto.retry/1","doc":"Retry a discarded or cancelled job. Uses the active transaction's pool, or the configured pool.","ref":"shigoto.html#retry/1"},{"type":"function","title":"shigoto.retry/2","doc":"Retry a discarded or cancelled job.","ref":"shigoto.html#retry/2"},{"type":"function","title":"shigoto.retry_by/1","doc":"Retry all jobs matching a filter. Uses the active transaction's pool, or the configured pool. Filters: worker, queue, state, tags.","ref":"shigoto.html#retry_by/1"},{"type":"function","title":"shigoto.retry_by/2","doc":"Retry all jobs matching a filter. Filters: worker, queue, state, tags.","ref":"shigoto.html#retry_by/2"},{"type":"function","title":"shigoto.transaction/1","doc":"Run `Fun` inside a database transaction on the Shigoto pool.\n\nJobs enqueued with `insert/1,2` or `insert_all/1,2` from within `Fun` commit\natomically with any other work done on the same pool: if `Fun` raises, the\ntransaction rolls back and no jobs are enqueued. `job_inserted` telemetry fires\nonly after a successful commit.\n\nTo roll back, raise an exception. If a statement inside `Fun` fails and aborts the\ntransaction, the commit is rejected and `transaction_rolled_back` is raised — no\njobs are enqueued and no telemetry fires. Returns the value of `Fun`.","ref":"shigoto.html#transaction/1"},{"type":"function","title":"shigoto.transaction/2","doc":"Like `transaction/1`, on a specific pool via `#{pool => Pool}`. Nested calls inherit the outer pool.","ref":"shigoto.html#transaction/2"},{"type":"module","title":"shigoto_app","doc":"OTP application callback for Shigoto.","ref":"shigoto_app.html"},{"type":"module","title":"shigoto_batch","doc":"Batch/workflow system for Shigoto. Groups jobs into batches with\ncompletion and discard callbacks.","ref":"shigoto_batch.html"},{"type":"module","title":"Usage - shigoto_batch","doc":"```erlang\n%% Create a batch with a callback worker\n{ok, Batch} = shigoto:new_batch(#{\n    callback_worker => my_batch_callback,\n    callback_args => #{<<\\\"report_id\\\">> => 42}\n}),\nBatchId = maps:get(id, Batch),\n\n%% Insert jobs into the batch\nshigoto:insert(#{worker => step_one, args => #{}, batch => BatchId}),\nshigoto:insert(#{worker => step_two, args => #{}, batch => BatchId}),\n\n%% When all jobs complete, my_batch_callback:perform/1 is called\n%% with the callback_args. If any job is discarded, the batch\n%% state changes to 'callback_discarding' and the callback is\n%% called with an added <<\\\"_batch_event\\\">> => <<\\\"discard\\\">> key.\n```","ref":"shigoto_batch.html#module-usage"},{"type":"function","title":"shigoto_batch.create/2","doc":"Create a new batch.","ref":"shigoto_batch.html#create/2"},{"type":"function","title":"shigoto_batch.get/2","doc":"Get a batch by ID.","ref":"shigoto_batch.html#get/2"},{"type":"function","title":"shigoto_batch.increment_total/2","doc":"Increment total job count for a batch.","ref":"shigoto_batch.html#increment_total/2"},{"type":"function","title":"shigoto_batch.job_completed/2","doc":"Record a completed job in the batch. May trigger callback.","ref":"shigoto_batch.html#job_completed/2"},{"type":"function","title":"shigoto_batch.job_discarded/2","doc":"Record a discarded job in the batch. May trigger callback.","ref":"shigoto_batch.html#job_discarded/2"},{"type":"module","title":"shigoto_config","doc":"Configuration access for Shigoto. Reads from application env.","ref":"shigoto_config.html"},{"type":"function","title":"shigoto_config.archive_after_days/0","doc":"Days to keep archived jobs before permanent deletion. Default: 90.","ref":"shigoto_config.html#archive_after_days/0"},{"type":"function","title":"shigoto_config.cron_entries/0","doc":"Cron job entries. Each is `{Name, Schedule, Worker, Args}` or\n`{Name, Schedule, Worker, Args, #{timezone => Timezone}}`.\n\n`Timezone` may be:\n- `utc` (the default when omitted)\n- an integer hour offset, e.g. `2` or `-5`\n- a `\"+/-N\"` or `\"UTC\"` binary, e.g. `<<\"+2\">>`\n- a named IANA zone, e.g. `<<\"Europe/Stockholm\">>`, resolved (with DST) for\n  each instant against the operating system's time zone database","ref":"shigoto_config.html#cron_entries/0"},{"type":"function","title":"shigoto_config.encryption_key/0","doc":"AES-256-GCM encryption key for job args/meta. Returns `undefined` if not configured.","ref":"shigoto_config.html#encryption_key/0"},{"type":"function","title":"shigoto_config.encryption_keys/0","doc":"Ordered list of encryption keys (newest first) for key rotation. Default: [].","ref":"shigoto_config.html#encryption_keys/0"},{"type":"function","title":"shigoto_config.fair_queues/0","doc":"Queues that use fair partition-based claiming. Default: [] (all use standard claiming).","ref":"shigoto_config.html#fair_queues/0"},{"type":"function","title":"shigoto_config.fanout_queues/0","doc":"Fanout queues — every node processes every job. Format:\n`[{QueueName, Concurrency, Opts}]` where Opts may include\n`window` (seconds, default 120). Default: [].","ref":"shigoto_config.html#fanout_queues/0"},{"type":"function","title":"shigoto_config.heartbeat_interval/0","doc":"Heartbeat interval in milliseconds for executing jobs. Default: 30000.","ref":"shigoto_config.html#heartbeat_interval/0"},{"type":"function","title":"shigoto_config.load_shedding/0","doc":"Load shedding config. Default: undefined (disabled).","ref":"shigoto_config.html#load_shedding/0"},{"type":"function","title":"shigoto_config.middleware/0","doc":"Global middleware chain applied to all jobs. Default: [].","ref":"shigoto_config.html#middleware/0"},{"type":"function","title":"shigoto_config.notifier_config/0","doc":"Database connection config for LISTEN/NOTIFY. Returns `undefined` if not configured.","ref":"shigoto_config.html#notifier_config/0"},{"type":"function","title":"shigoto_config.poll_interval/0","doc":"Poll interval in milliseconds. Default: 5000.","ref":"shigoto_config.html#poll_interval/0"},{"type":"function","title":"shigoto_config.pool/0","doc":"The minato pool name for job storage. Set `repo` for Kura-based apps or `pool` for a pool of its own.","ref":"shigoto_config.html#pool/0"},{"type":"function","title":"shigoto_config.prune_after_days/0","doc":"Days to keep completed/discarded jobs before archiving. Default: 14.","ref":"shigoto_config.html#prune_after_days/0"},{"type":"function","title":"shigoto_config.queue_weights/0","doc":"Queue weight config. Map of queue name to weight. Default: #{} (equal weight).","ref":"shigoto_config.html#queue_weights/0"},{"type":"function","title":"shigoto_config.queues/0","doc":"Configured queue names and concurrency. Default: `[{<<\"default\">>, 10}]`.","ref":"shigoto_config.html#queues/0"},{"type":"function","title":"shigoto_config.shutdown_timeout/0","doc":"Milliseconds to wait for in-flight jobs during shutdown. Default: 15000.","ref":"shigoto_config.html#shutdown_timeout/0"},{"type":"function","title":"shigoto_config.stage_interval/0","doc":"Stager interval in milliseconds for surfacing newly-due scheduled/retryable jobs. Default: 1000.","ref":"shigoto_config.html#stage_interval/0"},{"type":"function","title":"shigoto_config.testing_mode/0","doc":"Testing mode for `insert/1,2` and `insert_all/1,2`. Default: `disabled` (normal\nproduction behaviour — jobs are persisted and run by queue workers).\n\n`inline` executes each inserted job synchronously in the calling process and\nkeeps no database row; `manual` captures inserted jobs in a process-local buffer\nfor `m:shigoto_testing` assertions without persisting or executing them. Both are\nstrictly for tests: they change persistence, so arming them requires TWO keys —\n\n```erlang\napplication:set_env(shigoto, testing, inline),          %% or manual\napplication:set_env(shigoto, testing_confirm_no_persistence, true).\n```\n\nA non-`disabled` `testing` value WITHOUT the confirmation key does NOT arm the\nmode: it falls back to the real persisted path and logs an error, so a testing\nconfig that leaks into production fails safe and loud rather than silently\ndropping jobs.","ref":"shigoto_config.html#testing_mode/0"},{"type":"module","title":"shigoto_cron","doc":"Cron scheduler. Checks configured cron expressions every minute and\ninserts jobs for entries that are due. On startup, catches up on any\nmissed intervals since the last run.\n\nUses `pg_try_advisory_lock` so only one node runs cron checks\nin a multi-node deployment.\n\nEntries may carry a `timezone` in their `Opts` map (`utc`, an integer hour\noffset, a `\"+/-N\"`/`\"UTC\"` binary, or a named IANA zone such as\n`<<\"Europe/Stockholm\">>`). Named zones are resolved with DST via `m:shigoto_tz`.\nSee `shigoto_config:cron_entries/0`.","ref":"shigoto_cron.html"},{"type":"module","title":"shigoto_cron_parser","doc":"Parses standard 5-field cron expressions and checks if a given datetime\nmatches. Fields: minute, hour, day-of-month, month, day-of-week.\n\nSupported syntax per field:\n- `*` — any value\n- `N` — exact value\n- `N-M` — inclusive range\n- `*/N` — step from start\n- `N-M/S` — step within range\n- `N,M,O` — comma-separated list (each element may be a value, range, or step)\n\nAliases: `@yearly`, `@annually`, `@monthly`, `@weekly`, `@daily`, `@midnight`, `@hourly`.","ref":"shigoto_cron_parser.html"},{"type":"type","title":"shigoto_cron_parser.cron_expr/0","doc":"","ref":"shigoto_cron_parser.html#t:cron_expr/0"},{"type":"type","title":"shigoto_cron_parser.field/0","doc":"","ref":"shigoto_cron_parser.html#t:field/0"},{"type":"function","title":"shigoto_cron_parser.matches/2","doc":"Check if a `calendar:datetime()` matches a parsed cron expression.","ref":"shigoto_cron_parser.html#matches/2"},{"type":"function","title":"shigoto_cron_parser.parse/1","doc":"Parse a 5-field cron expression or alias into a structured map.","ref":"shigoto_cron_parser.html#parse/1"},{"type":"module","title":"shigoto_crypto","doc":"AES-256-GCM encryption for job args at rest.\n\nWhen encryption is configured, job arguments are encrypted before\ninsertion and decrypted after claiming. This is transparent to workers.","ref":"shigoto_crypto.html"},{"type":"module","title":"Single key - shigoto_crypto","doc":"```erlang\n{shigoto, [{encryption_key, <<\"32-byte-secret-key-here..........\">>}]}\n```","ref":"shigoto_crypto.html#module-single-key"},{"type":"module","title":"Key rotation - shigoto_crypto","doc":"Use `encryption_keys` (list, newest first). New jobs are encrypted with\nthe first key. Decryption tries each key until one succeeds.\n\n```erlang\n{shigoto, [{encryption_keys, [\n    <<\"new-32-byte-key..................\">>,\n    <<\"old-32-byte-key..................\">>\n]}]}\n```\n\nOld jobs are re-encrypted with the current key when claimed and re-inserted\n(e.g. via retry). The old key can be removed once all jobs encrypted with\nit have been processed.","ref":"shigoto_crypto.html#module-key-rotation"},{"type":"function","title":"shigoto_crypto.decrypt/1","doc":"Decrypt a binary, trying all configured keys. Returns the original binary if not encrypted.","ref":"shigoto_crypto.html#decrypt/1"},{"type":"function","title":"shigoto_crypto.encrypt/1","doc":"Encrypt a binary with the current key. Returns the original binary if not configured.","ref":"shigoto_crypto.html#encrypt/1"},{"type":"function","title":"shigoto_crypto.is_enabled/0","doc":"Check if encryption is configured.","ref":"shigoto_crypto.html#is_enabled/0"},{"type":"module","title":"shigoto_dashboard","doc":"Dashboard queries for Shigoto. Provides statistics and search functions\nfor building admin UIs, monitoring dashboards, and Nova Liveboard pages.","ref":"shigoto_dashboard.html"},{"type":"module","title":"Queue Statistics - shigoto_dashboard","doc":"```erlang\nshigoto_dashboard:queue_stats() ->\n    [#{queue => <<\\\"default\\\">>, available => 42, executing => 5,\n       retryable => 2, completed => 1000, discarded => 3}]\n```","ref":"shigoto_dashboard.html#module-queue-statistics"},{"type":"module","title":"Job Search - shigoto_dashboard","doc":"```erlang\nshigoto_dashboard:search_jobs(#{worker => my_worker, state => failed, limit => 20})\n```","ref":"shigoto_dashboard.html#module-job-search"},{"type":"function","title":"shigoto_dashboard.batch_stats/0","doc":"Get batch statistics.","ref":"shigoto_dashboard.html#batch_stats/0"},{"type":"function","title":"shigoto_dashboard.job_counts/0","doc":"Get global job counts by state.","ref":"shigoto_dashboard.html#job_counts/0"},{"type":"function","title":"shigoto_dashboard.queue_stats/0","doc":"Get per-queue job counts grouped by state.","ref":"shigoto_dashboard.html#queue_stats/0"},{"type":"function","title":"shigoto_dashboard.recent_failures/1","doc":"Get the most recent failed jobs.","ref":"shigoto_dashboard.html#recent_failures/1"},{"type":"function","title":"shigoto_dashboard.search_jobs/1","doc":"Search jobs with filters. Supports: worker, queue, state, tags, limit, offset.","ref":"shigoto_dashboard.html#search_jobs/1"},{"type":"function","title":"shigoto_dashboard.stale_jobs/0","doc":"Get jobs stuck in executing state (potential zombies).","ref":"shigoto_dashboard.html#stale_jobs/0"},{"type":"function","title":"shigoto_dashboard.worker_stats/0","doc":"Get per-worker job counts and average execution stats.","ref":"shigoto_dashboard.html#worker_stats/0"},{"type":"module","title":"shigoto_db","doc":"Every statement shigoto runs goes through here.\n\nThe client was called from ten modules directly, which meant changing it was\ntwenty five edits and a hope. It is one module now, and the rest of shigoto asks\nfor a query rather than for a driver.","ref":"shigoto_db.html"},{"type":"module","title":"What a caller gets - shigoto_db","doc":"`#{command := atom(), num_rows := integer(), rows := [row()]}` for a statement\nthat ran, and `{error, Reason}` for one that did not, with `{pgsql_error,\nFields}` as the reason a server refused it. That is the shape shigoto already\nreads everywhere.","ref":"shigoto_db.html#module-what-a-caller-gets"},{"type":"module","title":"Transactions - shigoto_db","doc":"`transaction/2` borrows one connection, runs `BEGIN`, calls the function, and\ncommits or rolls back. Statements the function runs find that connection here\nrather than being handed it, because a job queue's transaction functions are\nordinary code that calls `shigoto_repo` and cannot thread a connection through.\n\nA `COMMIT` the server answers with `ROLLBACK` raises `transaction_rolled_back`.\nPostgreSQL does that when the transaction had already failed, and a job queue\nthat reads it as success has marked jobs done that were never written - which is\nthe same job running twice on the next poll.","ref":"shigoto_db.html#module-transactions"},{"type":"type","title":"shigoto_db.error/0","doc":"What went wrong. `pgsql_error` is the server refusing the statement.","ref":"shigoto_db.html#t:error/0"},{"type":"type","title":"shigoto_db.result/0","doc":"The shape a statement answers with.","ref":"shigoto_db.html#t:result/0"},{"type":"function","title":"shigoto_db.in_transaction/1","doc":"The connection holding this process's transaction on `Pool`, or `undefined`.","ref":"shigoto_db.html#in_transaction/1"},{"type":"function","title":"shigoto_db.query/3","doc":"`query/4` with the default decoding: rows as maps, column names as atoms.","ref":"shigoto_db.html#query/3"},{"type":"function","title":"shigoto_db.query/4","doc":"Run one statement, on this process's transaction if it is inside one.\n\n`Opts` are minato's query options: `timeout` is a deadline after which the\nstatement is cancelled on the server rather than abandoned, and the decoding\noptions are the ones `m:minato_protocol` documents.","ref":"shigoto_db.html#query/4"},{"type":"function","title":"shigoto_db.start_listener/2","doc":"Start a listener for `LISTEN`, on a connection of its own.\n\n`LISTEN` is session state, so it cannot share the pool: a notification is\ndelivered to the session that registered for it, and a pooled connection would\ndeliver it to whichever caller happened to hold it next.","ref":"shigoto_db.html#start_listener/2"},{"type":"function","title":"shigoto_db.start_pool/2","doc":"Start a pool from shigoto's configuration.\n\nTakes what shigoto and its users already write - `host`, `port`, `database`,\n`user`, `password`, `pool_size` - and gives minato what it takes.","ref":"shigoto_db.html#start_pool/2"},{"type":"function","title":"shigoto_db.transaction/2","doc":"Run `Fun` inside a transaction on `Pool`.\n\nNested calls join the transaction that is already open rather than starting a\nsecond one, because SQL has no nested `BEGIN` and the caller usually does not\nknow whether it is nested.","ref":"shigoto_db.html#transaction/2"},{"type":"module","title":"shigoto_executor","doc":"Executes a single job through the middleware chain with seki resilience.\nStarted by the executor supervisor, reports back to the queue process when done.","ref":"shigoto_executor.html"},{"type":"function","title":"shigoto_executor.execute_sync/3","doc":"Execute a job synchronously (for drain_queue).","ref":"shigoto_executor.html#execute_sync/3"},{"type":"function","title":"shigoto_executor.run_perform/4","doc":"Run a worker through the exact perform path production uses: `deps_results`\ninjection + the middleware chain + `perform/1` under `Timeout`. Returns the raw\nworker result (`ok | {ok, Result} | {error, _} | {snooze, _}`).\n\nShared by the queue executor, `execute_sync/3`, and `shigoto:perform_job/2,3`.\nIt performs NO persistence, telemetry, retry, or resilience gating — those are the\ncaller's responsibility. Used by the testing helpers to run a worker with no DB.","ref":"shigoto_executor.html#run_perform/4"},{"type":"module","title":"shigoto_executor_sup","doc":"Dynamic supervisor for job executor processes.","ref":"shigoto_executor_sup.html"},{"type":"function","title":"shigoto_executor_sup.start_executor/3","doc":"Start a new executor process for a job.","ref":"shigoto_executor_sup.html#start_executor/3"},{"type":"module","title":"shigoto_fanout_queue","doc":"Fanout queue — every node processes every job. Used for broadcast\nevents like session revocation, notifications, and cross-node chat.\n\nUnlike the standard queue which uses FOR UPDATE SKIP LOCKED (single\nconsumer), fanout queues let all nodes read the same jobs. Each node\ntracks which job IDs it has already processed in a local ETS table.\n\nJobs are read within a time window (default 120s). Older jobs are\nignored. On node restart, the ETS is empty so recent jobs within the\nwindow are re-processed — workers must be idempotent.\n\nThe source of truth is always the database. Fanout is best-effort\npush; if a node misses a job, the client catches up on reconnect.","ref":"shigoto_fanout_queue.html"},{"type":"function","title":"shigoto_fanout_queue.handle_call/3","doc":"","ref":"shigoto_fanout_queue.html#handle_call/3"},{"type":"function","title":"shigoto_fanout_queue.handle_cast/2","doc":"","ref":"shigoto_fanout_queue.html#handle_cast/2"},{"type":"function","title":"shigoto_fanout_queue.handle_info/2","doc":"","ref":"shigoto_fanout_queue.html#handle_info/2"},{"type":"function","title":"shigoto_fanout_queue.init/1","doc":"","ref":"shigoto_fanout_queue.html#init/1"},{"type":"function","title":"shigoto_fanout_queue.start_link/3","doc":"","ref":"shigoto_fanout_queue.html#start_link/3"},{"type":"function","title":"shigoto_fanout_queue.terminate/2","doc":"","ref":"shigoto_fanout_queue.html#terminate/2"},{"type":"module","title":"shigoto_heartbeat","doc":"Heartbeat system for executing jobs. Periodically updates `heartbeat_at`\nfor all in-flight jobs on this node, enabling faster stale job detection.\n\nWithout heartbeat, stale jobs are detected after 5 minutes. With heartbeat,\na job is considered stale if its heartbeat is older than 2x the heartbeat\ninterval (default: 60 seconds).","ref":"shigoto_heartbeat.html"},{"type":"module","title":"shigoto_middleware","doc":"Composable middleware chain for job execution.\n\nMiddleware wraps job execution with before/after logic. Each middleware\nis a function that receives the job map and a `Next` function. Call `Next()`\nto continue the chain, or return early to short-circuit.","ref":"shigoto_middleware.html"},{"type":"module","title":"Writing Middleware - shigoto_middleware","doc":"```erlang\nmy_middleware(Job, Next) ->\n    %% Before\n    logger:info(\\\"starting job\\\", #{job_id => maps:get(id, Job)}),\n    Result = Next(),\n    %% After\n    logger:info(\\\"finished job\\\", #{job_id => maps:get(id, Job)}),\n    Result.\n```","ref":"shigoto_middleware.html#module-writing-middleware"},{"type":"module","title":"Middleware Order - shigoto_middleware","doc":"Built-in middleware runs in this order:\n1. Logger metadata (sets structured log context)\n2. Seki resilience (rate limit, bulkhead, circuit breaker)\n3. Global middleware (from config)\n4. Worker middleware (from worker callback)\n5. Worker:perform/1","ref":"shigoto_middleware.html#module-middleware-order"},{"type":"type","title":"shigoto_middleware.middleware/0","doc":"","ref":"shigoto_middleware.html#t:middleware/0"},{"type":"type","title":"shigoto_middleware.result/0","doc":"","ref":"shigoto_middleware.html#t:result/0"},{"type":"function","title":"shigoto_middleware.build_chain/3","doc":"Build a composed function from a middleware list.","ref":"shigoto_middleware.html#build_chain/3"},{"type":"function","title":"shigoto_middleware.run/3","doc":"Run the full middleware chain for a job.","ref":"shigoto_middleware.html#run/3"},{"type":"module","title":"shigoto_migration","doc":"Database migrations for Shigoto tables. Call `up/1` with a minato pool name\nto create or update the jobs and cron tables.\n\nMigrations are idempotent and safe to run multiple times.","ref":"shigoto_migration.html"},{"type":"function","title":"shigoto_migration.down/1","doc":"Drop the shigoto tables.","ref":"shigoto_migration.html#down/1"},{"type":"function","title":"shigoto_migration.up/1","doc":"Create or update the shigoto_jobs and shigoto_cron tables.","ref":"shigoto_migration.html#up/1"},{"type":"module","title":"shigoto_notifier","doc":"Listens for PostgreSQL NOTIFY events on the `shigoto_jobs_insert` channel\nand triggers immediate polling on the relevant queue. Falls back to\nregular polling if the notification connection drops.\n\nA notification is an optimisation, never the only path: `NOTIFY` has no replay,\nso anything published while the listener was away is gone. minato says when that\nhappened, and this process answers it by polling every queue once, which is the\ncatch up the missed notifications would have caused.\n\nRequires `notifier` config with database connection details:\n\n```erlang\n{shigoto, [\n    {pool, my_db},\n    {notifier, #{host => \"localhost\", port => 5432,\n                 database => \"mydb\", user => \"postgres\", password => \"secret\"}}\n]}\n```\n\nWithout `notifier` config, this process is not started and shigoto\nrelies solely on polling.","ref":"shigoto_notifier.html"},{"type":"module","title":"shigoto_pruner","doc":"Periodically archives old completed and discarded jobs. Moves them\nto `shigoto_jobs_archive` before deleting from the main table, then\ndeletes archived rows older than the configured retention window so the\narchive stays bounded.","ref":"shigoto_pruner.html"},{"type":"module","title":"shigoto_queue","doc":"Per-queue gen_server that polls for available jobs and dispatches\nthem to the executor supervisor. Supports graceful shutdown, queue\nweights, and pause/resume.","ref":"shigoto_queue.html"},{"type":"function","title":"shigoto_queue.pause/1","doc":"Pause a queue — stops claiming new jobs but lets in-flight jobs finish.","ref":"shigoto_queue.html#pause/1"},{"type":"function","title":"shigoto_queue.resume/1","doc":"Resume a paused queue.","ref":"shigoto_queue.html#resume/1"},{"type":"module","title":"shigoto_queue_sup","doc":"Supervisor for per-queue polling processes.","ref":"shigoto_queue_sup.html"},{"type":"module","title":"shigoto_repo","doc":"All SQL operations for Shigoto jobs. Uses `FOR UPDATE SKIP LOCKED`\nfor safe multi-node job claiming.","ref":"shigoto_repo.html"},{"type":"function","title":"shigoto_repo.archive_jobs/2","doc":"Archive completed/discarded/cancelled jobs older than given days. Moves to archive table then deletes.","ref":"shigoto_repo.html#archive_jobs/2"},{"type":"function","title":"shigoto_repo.cancel_by/2","doc":"Cancel jobs matching a pattern. Supports worker, queue, tags filters.","ref":"shigoto_repo.html#cancel_by/2"},{"type":"function","title":"shigoto_repo.cancel_job/2","doc":"Cancel a job. Resolves dependencies so dependent jobs aren't stuck.","ref":"shigoto_repo.html#cancel_job/2"},{"type":"function","title":"shigoto_repo.claim_jobs/3","doc":"Claim up to N available jobs from a queue using FOR UPDATE SKIP LOCKED.","ref":"shigoto_repo.html#claim_jobs/3"},{"type":"function","title":"shigoto_repo.claim_jobs_fair/3","doc":"Claim jobs with fair partition interleaving. One job per partition first, then fill.","ref":"shigoto_repo.html#claim_jobs_fair/3"},{"type":"function","title":"shigoto_repo.complete_job/2","doc":"Mark a job as completed with no result. Equivalent to `complete_job/3` with `null`.","ref":"shigoto_repo.html#complete_job/2"},{"type":"function","title":"shigoto_repo.complete_job/3","doc":"Mark a job as completed and store its JSON-encodable result on the row.\n\nThe result is propagated to any jobs that depend on this one (see\n`resolve_dependencies/2`) so they can read it via `deps_results`.","ref":"shigoto_repo.html#complete_job/3"},{"type":"function","title":"shigoto_repo.discard_job/2","doc":"Mark a job as discarded. Resolves dependencies so dependent jobs aren't stuck.","ref":"shigoto_repo.html#discard_job/2"},{"type":"function","title":"shigoto_repo.fail_job/4","doc":"Record a job failure with structured error and configurable backoff.","ref":"shigoto_repo.html#fail_job/4"},{"type":"function","title":"shigoto_repo.fetch_fanout_jobs/3","doc":"Fetch recent jobs for fanout queues. No locking — all nodes read the same rows.","ref":"shigoto_repo.html#fetch_fanout_jobs/3"},{"type":"function","title":"shigoto_repo.find_jobs/2","doc":"Find jobs matching a filter map. Read-only; used by the testing helpers'\nDB-backed enqueue assertions.\n\nFilters: `worker`, `queue`, `args` (jsonb containment), `tags` (array\ncontainment), and `state` (a state binary or a list of them). An empty filter\nreturns all jobs. Args are decrypted so callers can match on plaintext.","ref":"shigoto_repo.html#find_jobs/2"},{"type":"function","title":"shigoto_repo.get_due_cron_entries/1","doc":"Get cron entries that are due for scheduling.","ref":"shigoto_repo.html#get_due_cron_entries/1"},{"type":"function","title":"shigoto_repo.get_job/2","doc":"Get a job by ID.","ref":"shigoto_repo.html#get_job/2"},{"type":"function","title":"shigoto_repo.insert_all/3","doc":"Bulk insert multiple jobs in a single SQL statement. Returns inserted jobs.","ref":"shigoto_repo.html#insert_all/3"},{"type":"function","title":"shigoto_repo.insert_job/3","doc":"Insert a new job. Respects worker defaults and unique constraints. Validates dependency cycles.","ref":"shigoto_repo.html#insert_job/3"},{"type":"function","title":"shigoto_repo.prune_archive/2","doc":"Delete archived jobs older than given days. Bounds the archive table.","ref":"shigoto_repo.html#prune_archive/2"},{"type":"function","title":"shigoto_repo.prune_jobs/2","doc":"Delete completed/discarded jobs older than given days.","ref":"shigoto_repo.html#prune_jobs/2"},{"type":"function","title":"shigoto_repo.rescue_stale_jobs/2","doc":"Rescue stale executing jobs. Uses heartbeat if available, otherwise attempted_at.","ref":"shigoto_repo.html#rescue_stale_jobs/2"},{"type":"function","title":"shigoto_repo.resolve_dependencies/2","doc":"Resolve dependencies of a finished job.\n\nRemoves the finished job ID from every dependent's `depends_on` array (which\nungates the dependent once its last predecessor clears) and records the\nfinished job's `result` under its ID in each dependent's `deps_results`. A job\nthat produced no result (plain completion, discard, or cancel) contributes a\nJSON `null`.","ref":"shigoto_repo.html#resolve_dependencies/2"},{"type":"function","title":"shigoto_repo.retry_by/2","doc":"Retry all jobs matching a filter. Supports worker, queue, state, tags.","ref":"shigoto_repo.html#retry_by/2"},{"type":"function","title":"shigoto_repo.retry_job/2","doc":"Retry a discarded or cancelled job by resetting to available.","ref":"shigoto_repo.html#retry_job/2"},{"type":"function","title":"shigoto_repo.snooze_job/3","doc":"Snooze a job — reschedule for later without counting as a failure.","ref":"shigoto_repo.html#snooze_job/3"},{"type":"function","title":"shigoto_repo.update_progress/3","doc":"Update job progress (0-100).","ref":"shigoto_repo.html#update_progress/3"},{"type":"function","title":"shigoto_repo.upsert_cron_entry/2","doc":"Upsert a cron entry.","ref":"shigoto_repo.html#upsert_cron_entry/2"},{"type":"module","title":"shigoto_resilience","doc":"Seki-based resilience integration for Shigoto workers.\n\nProvides per-worker rate limiting, circuit breaking, bulkhead (concurrency\nlimiting), and system-level load shedding. All primitives are lazily\ninitialized on first use based on worker callbacks.","ref":"shigoto_resilience.html"},{"type":"module","title":"Rate Limiting - shigoto_resilience","doc":"Workers that export `rate_limit/0` get per-worker rate limiting via seki.\nJobs that hit the rate limit are snoozed (rescheduled for later) rather than failed.","ref":"shigoto_resilience.html#module-rate-limiting"},{"type":"module","title":"Circuit Breaking - shigoto_resilience","doc":"When a worker fails repeatedly, its circuit breaker opens and subsequent\njobs are snoozed until the breaker transitions to half-open, keeping work\noff a known-broken dependency.","ref":"shigoto_resilience.html#module-circuit-breaking"},{"type":"module","title":"Bulkhead - shigoto_resilience","doc":"Workers that export `concurrency/0` get a global concurrency limit across\nall queues. This is separate from per-queue concurrency.","ref":"shigoto_resilience.html#module-bulkhead"},{"type":"module","title":"Load Shedding - shigoto_resilience","doc":"System-level CoDel-based load shedding can be enabled via config. Low-priority\njobs are shed first when the system is overloaded.","ref":"shigoto_resilience.html#module-load-shedding"},{"type":"function","title":"shigoto_resilience.check_bulkhead/2","doc":"Check per-worker bulkhead. Returns ok or {snooze, 5}.","ref":"shigoto_resilience.html#check_bulkhead/2"},{"type":"function","title":"shigoto_resilience.check_circuit/2","doc":"Check circuit breaker for a worker. Returns ok or {snooze, 10}.","ref":"shigoto_resilience.html#check_circuit/2"},{"type":"function","title":"shigoto_resilience.check_global_concurrency/2","doc":"Check the per-worker global concurrency limit across all nodes via PostgreSQL.\n\nThe check-and-admit is serialised per worker with a PostgreSQL transaction-scoped\nadvisory lock, so two nodes can never both admit a job past the cap. It counts\n*other* jobs of the worker already `executing` (excluding the job being checked,\nwhich claiming has already marked `executing`), so a job at exactly the limit is\nnot spuriously snoozed. When the limit is reached the job's slot is freed back to\n`available` inside the same locked transaction, so the next serialised checker\nobserves the reduced count. That makes a burst of concurrently claimed jobs snooze\none at a time until exactly `global_concurrency/0` remain running, instead of all\nsnoozing together and livelocking.\n\nReturns `ok` or `{snooze, Seconds}`. Fails open (`ok`) on any database error, so a\ntransient DB problem never turns the check into a job failure.","ref":"shigoto_resilience.html#check_global_concurrency/2"},{"type":"function","title":"shigoto_resilience.check_load/1","doc":"Execute through circuit breaker, returning the result.","ref":"shigoto_resilience.html#check_load/1"},{"type":"function","title":"shigoto_resilience.check_rate_limit/2","doc":"Check per-worker rate limit. Returns ok or {snooze, Seconds}.","ref":"shigoto_resilience.html#check_rate_limit/2"},{"type":"function","title":"shigoto_resilience.complete_load/2","doc":"Report load shedder completion.","ref":"shigoto_resilience.html#complete_load/2"},{"type":"function","title":"shigoto_resilience.ensure_worker_primitives/1","doc":"Ensure seki primitives exist for a worker. Lazy and idempotent.","ref":"shigoto_resilience.html#ensure_worker_primitives/1"},{"type":"function","title":"shigoto_resilience.release_bulkhead/1","doc":"Release bulkhead slot for a worker.","ref":"shigoto_resilience.html#release_bulkhead/1"},{"type":"function","title":"shigoto_resilience.setup_load_shedder/0","doc":"Set up system-level load shedder if configured.","ref":"shigoto_resilience.html#setup_load_shedder/0"},{"type":"module","title":"shigoto_stager","doc":"Latency accelerator for delayed jobs. On a short interval it finds\nqueues with work due to run now (a job's `scheduled_at` has elapsed,\nincluding a failed job rescheduled after its backoff) and issues a\n`pg_notify('shigoto_jobs_insert', Queue)` so the existing notifier\nwakes the matching queue immediately instead of waiting up to\n`poll_interval`.\n\nUses `pg_try_advisory_xact_lock` so only one node stages in a\nmulti-node deployment; the notification still reaches every node.\n\nStarted only when the `notifier` is configured. The per-queue polling\nfallback remains the correctness backstop; the stager only reduces\nlatency, and fails soft on any database error so a transient fault\nnever crashes the supervision tree.","ref":"shigoto_stager.html"},{"type":"function","title":"shigoto_stager.due_queues/1","doc":"Return the distinct queues with jobs that are due to run right now.","ref":"shigoto_stager.html#due_queues/1"},{"type":"function","title":"shigoto_stager.stage_once/0","doc":"Run one staging pass synchronously (leader-gated). Fails soft. Mainly for testing.","ref":"shigoto_stager.html#stage_once/0"},{"type":"module","title":"shigoto_sup","doc":"Top-level supervisor for Shigoto. Starts the queue supervisor, cron\nscheduler, pruner, heartbeat, and optional LISTEN/NOTIFY notifier\nplus its due-job stager.","ref":"shigoto_sup.html"},{"type":"module","title":"shigoto_telemetry","doc":"Telemetry events for Shigoto job lifecycle, queue operations, and resilience.\n\nEvery event is emitted through `telemetry:execute/3`. The tables below are the\nstable event contract: attach a handler to any of these event names to feed a\nmetrics reporter (`telemetry_metrics`, Prometheus, StatsD, ...). See the\n[Telemetry](telemetry.md) guide for a worked `telemetry_metrics` example.\n\nMeasurement units:\n\n- `count` is always `1` (increment a counter/sum).\n- `duration` is in **native** time units (`erlang:monotonic_time/0` deltas).\n- `duration_ms`, `queue_wait_ms`, `retry_after_ms` are **milliseconds**.\n- `progress` is a **percentage** (`0..100`).\n- `claimed` is a **job count** (jobs claimed by that poll).\n\nEvery event carries `domain => [shigoto]` in its metadata (used by the OTP\nlogger for filtering); it is omitted from the tables below for brevity.","ref":"shigoto_telemetry.html"},{"type":"module","title":"Job Events - shigoto_telemetry","doc":"| Event | Measurements | Metadata |\n|-------|-------------|----------|\n| `[shigoto, job, inserted]` | `count` | job_id, worker, queue, attempt, priority |\n| `[shigoto, job, claimed]` | `count, queue_wait_ms` | job_id, worker, queue, attempt, priority |\n| `[shigoto, job, completed]` | `count, duration, duration_ms, queue_wait_ms` | job_id, worker, queue, attempt, priority |\n| `[shigoto, job, failed]` | `count, duration, duration_ms, queue_wait_ms` | job_id, worker, queue, attempt, priority, reason |\n| `[shigoto, job, snoozed]` | `count` | job_id, worker, queue, attempt, priority, snooze_reason |\n| `[shigoto, job, discarded]` | `count` | job_id, worker, queue, attempt, priority |\n| `[shigoto, job, cancelled]` | `count` | job_id, worker, queue, attempt, priority |\n| `[shigoto, job, progress]` | `progress` | job_id, worker, queue, attempt, priority, progress |","ref":"shigoto_telemetry.html#module-job-events"},{"type":"module","title":"Queue Events - shigoto_telemetry","doc":"| Event | Measurements | Metadata |\n|-------|-------------|----------|\n| `[shigoto, queue, poll]` | `count, claimed` | queue |\n| `[shigoto, queue, paused]` | `count` | queue |\n| `[shigoto, queue, resumed]` | `count` | queue |","ref":"shigoto_telemetry.html#module-queue-events"},{"type":"module","title":"Resilience Events - shigoto_telemetry","doc":"| Event | Measurements | Metadata |\n|-------|-------------|----------|\n| `[shigoto, resilience, rate_limited]` | `count, retry_after_ms` | worker |\n| `[shigoto, resilience, circuit_open]` | `count` | worker |\n| `[shigoto, resilience, bulkhead_full]` | `count` | worker |\n| `[shigoto, resilience, load_shed]` | `count` | priority |","ref":"shigoto_telemetry.html#module-resilience-events"},{"type":"module","title":"Batch Events - shigoto_telemetry","doc":"| Event | Measurements | Metadata |\n|-------|-------------|----------|\n| `[shigoto, batch, completed]` | `count` | batch_id, total_jobs, completed_jobs, discarded_jobs |","ref":"shigoto_telemetry.html#module-batch-events"},{"type":"module","title":"Cron Events - shigoto_telemetry","doc":"| Event | Measurements | Metadata |\n|-------|-------------|----------|\n| `[shigoto, cron, scheduled]` | `count` | name, worker, schedule |","ref":"shigoto_telemetry.html#module-cron-events"},{"type":"module","title":"Testing Events - shigoto_telemetry","doc":"| Event | Measurements | Metadata |\n|-------|-------------|----------|\n| `[shigoto, testing, mode_armed]` | `count` | mode |\n\nEmitted once at boot when a non-production `testing` mode (`inline`/`manual`) is\narmed. Its presence in a production metrics stream is a red flag — test-only\ninsert behaviour is active. See `shigoto_config:testing_mode/0`.","ref":"shigoto_telemetry.html#module-testing-events"},{"type":"function","title":"shigoto_telemetry.batch_completed/1","doc":"","ref":"shigoto_telemetry.html#batch_completed/1"},{"type":"function","title":"shigoto_telemetry.cron_scheduled/3","doc":"","ref":"shigoto_telemetry.html#cron_scheduled/3"},{"type":"function","title":"shigoto_telemetry.job_cancelled/1","doc":"","ref":"shigoto_telemetry.html#job_cancelled/1"},{"type":"function","title":"shigoto_telemetry.job_claimed/1","doc":"","ref":"shigoto_telemetry.html#job_claimed/1"},{"type":"function","title":"shigoto_telemetry.job_completed/2","doc":"","ref":"shigoto_telemetry.html#job_completed/2"},{"type":"function","title":"shigoto_telemetry.job_discarded/1","doc":"","ref":"shigoto_telemetry.html#job_discarded/1"},{"type":"function","title":"shigoto_telemetry.job_failed/3","doc":"","ref":"shigoto_telemetry.html#job_failed/3"},{"type":"function","title":"shigoto_telemetry.job_inserted/1","doc":"","ref":"shigoto_telemetry.html#job_inserted/1"},{"type":"function","title":"shigoto_telemetry.job_progress/2","doc":"","ref":"shigoto_telemetry.html#job_progress/2"},{"type":"function","title":"shigoto_telemetry.job_snoozed/2","doc":"","ref":"shigoto_telemetry.html#job_snoozed/2"},{"type":"function","title":"shigoto_telemetry.queue_paused/1","doc":"","ref":"shigoto_telemetry.html#queue_paused/1"},{"type":"function","title":"shigoto_telemetry.queue_poll/2","doc":"","ref":"shigoto_telemetry.html#queue_poll/2"},{"type":"function","title":"shigoto_telemetry.queue_resumed/1","doc":"","ref":"shigoto_telemetry.html#queue_resumed/1"},{"type":"function","title":"shigoto_telemetry.resilience_bulkhead_full/1","doc":"","ref":"shigoto_telemetry.html#resilience_bulkhead_full/1"},{"type":"function","title":"shigoto_telemetry.resilience_circuit_open/1","doc":"","ref":"shigoto_telemetry.html#resilience_circuit_open/1"},{"type":"function","title":"shigoto_telemetry.resilience_load_shed/1","doc":"","ref":"shigoto_telemetry.html#resilience_load_shed/1"},{"type":"function","title":"shigoto_telemetry.resilience_rate_limited/2","doc":"","ref":"shigoto_telemetry.html#resilience_rate_limited/2"},{"type":"function","title":"shigoto_telemetry.testing_mode_armed/1","doc":"","ref":"shigoto_telemetry.html#testing_mode_armed/1"},{"type":"module","title":"shigoto_testing","doc":"Test helpers for Shigoto: run workers with no database, and assert on the jobs\nyour code enqueued.","ref":"shigoto_testing.html"},{"type":"module","title":"Running a worker (shigoto:perform_job/2,3) - shigoto_testing","doc":"`shigoto:perform_job/2,3` runs a worker through the exact perform path production\nuses (the middleware chain and `deps_results` injection) and returns the raw\nworker result, with no database, no queue, no retry, and no resilience gating\n(rate limits, circuit breakers, concurrency caps are skipped). It is a pure,\nin-process unit-test runner — it must never be used on a production path.\n\n```erlang\nok = shigoto:perform_job(email_worker, #{~\"to\" => ~\"a@b.com\"}),\n{ok, Total} = shigoto:perform_job(sum_worker, #{~\"xs\" => [1, 2, 3]}),\n%% predecessors' results, exactly as a real dependent would see them:\n{ok, _} = shigoto:perform_job(rollup_worker, #{}, #{deps_results => #{41 => #{~\"n\" => 7}}}).\n```","ref":"shigoto_testing.html#module-running-a-worker-shigoto-perform_job-2-3"},{"type":"module","title":"Testing modes - shigoto_testing","doc":"Set a testing mode so `insert/1,2` and `insert_all/1,2` stop persisting. Both keys\nare required — see `shigoto_config:testing_mode/0` for why:\n\n```erlang\napplication:set_env(shigoto, testing, manual),\napplication:set_env(shigoto, testing_confirm_no_persistence, true).\n```\n\n- `inline` runs each inserted job synchronously and keeps no row. A job that\n  returns `{error, _}` raises `{shigoto_inline_job_failed, Worker, Reason}` so\n  failures surface loudly in the test.\n- `manual` captures inserted jobs in a **process-local** buffer without running\n  or persisting them, for the assertions below.\n\n`manual` capture is per-process: it sees enqueues made by the calling process,\nnot by other processes it spawned. For cross-process expectations, run against a\nreal test pool (the assertions fall back to querying the pool when not in\n`manual` mode) and clean the table between tests.","ref":"shigoto_testing.html#module-testing-modes"},{"type":"module","title":"Assertions - shigoto_testing","doc":"```erlang\nmy_code_that_enqueues(),\nshigoto_testing:assert_enqueued(#{worker => email_worker}),\nshigoto_testing:refute_enqueued(#{queue => ~\"sms\"}),\n[_ | _] = shigoto_testing:all_enqueued().\n```\n\nFilters: `worker`, `queue`, `args` (containment), `tags` (containment), `state`.\nCall `reset/0` in your test setup to clear the `manual` buffer.","ref":"shigoto_testing.html#module-assertions"},{"type":"function","title":"shigoto_testing.all_enqueued/0","doc":"All enqueued jobs (manual buffer, or the configured pool otherwise).","ref":"shigoto_testing.html#all_enqueued/0"},{"type":"function","title":"shigoto_testing.all_enqueued/1","doc":"Enqueued jobs matching a filter map.","ref":"shigoto_testing.html#all_enqueued/1"},{"type":"function","title":"shigoto_testing.assert_enqueued/1","doc":"Assert at least one enqueued job matches the filter; raises otherwise.","ref":"shigoto_testing.html#assert_enqueued/1"},{"type":"function","title":"shigoto_testing.assert_enqueued/2","doc":"Assert with options; `#{pool => Pool}` overrides the pool for the DB-backed path.","ref":"shigoto_testing.html#assert_enqueued/2"},{"type":"function","title":"shigoto_testing.perform_job/2","doc":"Run a worker with default job context. See the module doc.","ref":"shigoto_testing.html#perform_job/2"},{"type":"function","title":"shigoto_testing.perform_job/3","doc":"Run a worker with extra job context in `Opts`: `deps_results`, `attempt`,\n`max_attempts`, `queue`, `id`, `meta`, `tags`, `priority`, `timeout`.","ref":"shigoto_testing.html#perform_job/3"},{"type":"function","title":"shigoto_testing.refute_enqueued/1","doc":"Assert NO enqueued job matches the filter; raises with the matches otherwise.","ref":"shigoto_testing.html#refute_enqueued/1"},{"type":"function","title":"shigoto_testing.reset/0","doc":"Clear the manual-mode capture buffer for the calling process.","ref":"shigoto_testing.html#reset/0"},{"type":"module","title":"shigoto_tz","doc":"Resolves IANA named time zones (e.g. `<<\"Europe/Stockholm\">>`) to their UTC\noffset at a specific instant, accounting for daylight saving time.\n\nReads the operating system's IANA time zone database directly (TZif files,\nRFC 8536) from `$TZDIR` or `/usr/share/zoneinfo`. There is no external\ndependency and no build step: the database is kept current by the OS.\n\nOffsets are resolved from the file's explicit transition table. For instants\nbeyond the last recorded transition, the trailing POSIX TZ rule is evaluated so\nfuture dates stay correct.","ref":"shigoto_tz.html"},{"type":"function","title":"shigoto_tz.offset/2","doc":"UTC offset in seconds for `Zone` at the given UTC datetime, e.g.\n`{ok, 7200}` for `<<\"Europe/Stockholm\">>` during summer time.","ref":"shigoto_tz.html#offset/2"},{"type":"behaviour","title":"shigoto_worker","doc":"Behaviour for Shigoto job workers. Implement `perform/1` to handle jobs.\n\nThe `perform/1` callback receives the job's args map and should return\n`ok` on success or `{error, Reason}` on failure. Failed jobs are retried\nwith configurable backoff up to `max_attempts`.","ref":"shigoto_worker.html"},{"type":"behaviour","title":"Workflow Context - shigoto_worker","doc":"Return `{ok, Result}` to store a JSON-encodable `Result` on the job. Any job\nthat lists this one in its `depends_on` can then read that value. Plain `ok`\nstores a JSON `null`. Keep `Result` small (ids, status, a summary) — it is\ncopied into every dependent's `deps_results`, so large payloads fan out.\n\nWhen a job has dependencies, its args map carries a `deps_results` key holding\nthe predecessors' results, keyed by predecessor job ID:\n\n```erlang\nperform(#{~\"x\" := X, deps_results := #{ParentId := ParentResult}}) ->\n    ...\n```\n\nThe map shape is `#{PredId :: integer() => Result :: term()}`. A predecessor\nthat returned plain `ok` (or was discarded/cancelled) contributes `null`. The\n`deps_results` key is absent for jobs with no dependencies, so existing workers\nare unaffected.","ref":"shigoto_worker.html#module-workflow-context"},{"type":"behaviour","title":"Optional Callbacks - shigoto_worker","doc":"Workers can declare defaults via optional callbacks:\n\n- `max_attempts/0` — Maximum retry attempts (default: 3)\n- `queue/0` — Default queue name (default: `<<\\\"default\\\">>`)\n- `priority/0` — Default priority (default: 0)\n- `timeout/0` — Execution timeout in ms (default: 300000 / 5 min)\n- `unique/0` — Uniqueness constraints (see below)\n- `tags/0` — Default tags for this worker\n- `backoff/2` — Custom backoff strategy (attempt, error -> seconds)\n- `rate_limit/0` — Per-worker rate limit config for seki\n- `concurrency/0` — Max concurrent executions (local, per-node via seki bulkhead)\n- `global_concurrency/0` — Max concurrent executions across all nodes (via PostgreSQL)\n- `middleware/0` — Worker-specific middleware list\n- `on_discard/2` — Called when a job is permanently discarded\n- `circuit_breaker/0` — Per-worker circuit breaker config\n\nThese are used as defaults when inserting jobs. Per-insert options\nin the params map always take precedence.","ref":"shigoto_worker.html#module-optional-callbacks"},{"type":"behaviour","title":"Uniqueness - shigoto_worker","doc":"Implement `unique/0` to prevent duplicate jobs:\n\n```erlang\nunique() ->\n    #{\n        keys => [worker, args],     %% Fields to check (worker, args, queue)\n        states => [available, executing, retryable],  %% States to check against\n        period => 300               %% Seconds (or infinity)\n    }.\n```","ref":"shigoto_worker.html#module-uniqueness"},{"type":"behaviour","title":"Rate Limiting - shigoto_worker","doc":"Implement `rate_limit/0` to limit job execution rate:\n\n```erlang\nrate_limit() ->\n    #{\n        limit => 100,           %% Max requests per window\n        window => 60000,        %% Window in milliseconds\n        algorithm => sliding_window  %% token_bucket | sliding_window | gcra | leaky_bucket\n    }.\n```","ref":"shigoto_worker.html#module-rate-limiting"},{"type":"behaviour","title":"Custom Backoff - shigoto_worker","doc":"Implement `backoff/2` to control retry delays:\n\n```erlang\nbackoff(Attempt, _Error) ->\n    min(Attempt * 10, 300).  %% Linear backoff, max 5 minutes\n```","ref":"shigoto_worker.html#module-custom-backoff"},{"type":"behaviour","title":"Example - shigoto_worker","doc":"```erlang\n-module(cleanup_worker).\n-behaviour(shigoto_worker).\n-export([perform/1, max_attempts/0, queue/0, timeout/0, unique/0]).\n\nperform(#{<<\\\"days\\\">> := Days}) ->\n    delete_old_records(Days),\n    ok.\n\nmax_attempts() -> 5.\nqueue() -> <<\\\"maintenance\\\">>.\ntimeout() -> 60000. %% 1 minute\nunique() -> #{keys => [worker, args], period => 300}.\n```","ref":"shigoto_worker.html#module-example"},{"type":"type","title":"shigoto_worker.circuit_breaker_opts/0","doc":"","ref":"shigoto_worker.html#t:circuit_breaker_opts/0"},{"type":"type","title":"shigoto_worker.rate_limit_opts/0","doc":"","ref":"shigoto_worker.html#t:rate_limit_opts/0"},{"type":"type","title":"shigoto_worker.unique_opts/0","doc":"","ref":"shigoto_worker.html#t:unique_opts/0"},{"type":"callback","title":"shigoto_worker.backoff/2","doc":"","ref":"shigoto_worker.html#c:backoff/2"},{"type":"callback","title":"shigoto_worker.circuit_breaker/0","doc":"","ref":"shigoto_worker.html#c:circuit_breaker/0"},{"type":"callback","title":"shigoto_worker.concurrency/0","doc":"","ref":"shigoto_worker.html#c:concurrency/0"},{"type":"callback","title":"shigoto_worker.global_concurrency/0","doc":"","ref":"shigoto_worker.html#c:global_concurrency/0"},{"type":"callback","title":"shigoto_worker.max_attempts/0","doc":"","ref":"shigoto_worker.html#c:max_attempts/0"},{"type":"callback","title":"shigoto_worker.middleware/0","doc":"","ref":"shigoto_worker.html#c:middleware/0"},{"type":"callback","title":"shigoto_worker.on_discard/2","doc":"","ref":"shigoto_worker.html#c:on_discard/2"},{"type":"callback","title":"shigoto_worker.perform/1","doc":"","ref":"shigoto_worker.html#c:perform/1"},{"type":"callback","title":"shigoto_worker.priority/0","doc":"","ref":"shigoto_worker.html#c:priority/0"},{"type":"callback","title":"shigoto_worker.queue/0","doc":"","ref":"shigoto_worker.html#c:queue/0"},{"type":"callback","title":"shigoto_worker.rate_limit/0","doc":"","ref":"shigoto_worker.html#c:rate_limit/0"},{"type":"callback","title":"shigoto_worker.tags/0","doc":"","ref":"shigoto_worker.html#c:tags/0"},{"type":"callback","title":"shigoto_worker.timeout/0","doc":"","ref":"shigoto_worker.html#c:timeout/0"},{"type":"callback","title":"shigoto_worker.unique/0","doc":"","ref":"shigoto_worker.html#c:unique/0"},{"type":"extras","title":"Shigoto 仕事","doc":"# Shigoto 仕事\n\nPostgreSQL-backed background job processing for Erlang.\n\nShigoto (仕事, \"work\") is a feature-rich job queue built on PostgreSQL's `FOR UPDATE SKIP LOCKED` for safe multi-node operation. No Redis or external broker needed — if you have PostgreSQL, you have a job queue.","ref":"readme.html"},{"type":"extras","title":"Features - Shigoto 仕事","doc":"","ref":"readme.html#features"},{"type":"extras","title":"Core - Shigoto 仕事","doc":"- **PostgreSQL-backed** — Jobs stored in PostgreSQL via [pgo](https://github.com/erleans/pgo). Transactional enqueue using the same pool as your application.\n- **Multi-node safe** — `FOR UPDATE SKIP LOCKED` ensures each job is claimed by exactly one node. No coordination required.\n- **Priority queues** — Higher priority jobs are claimed first. Multiple queues with independent concurrency limits.\n- **Dynamic queues** — Add and remove queues at runtime without restart.\n- **Exponential backoff** — Failed jobs retry with `min(attempt^4 + jitter, 1800)` second delays, or provide a custom `backoff/2` callback.","ref":"readme.html#core"},{"type":"extras","title":"Scheduling - Shigoto 仕事","doc":"- **Cron scheduling** — Built-in 5-field cron parser with leader election via advisory locks. Catches up on missed intervals after restarts.\n- **Scheduled jobs** — Enqueue jobs for future execution with `scheduled_at`.\n- **Job snoozing** — Workers can return `{snooze, Seconds}` to reschedule without consuming a retry attempt.","ref":"readme.html#scheduling"},{"type":"extras","title":"Reliability - Shigoto 仕事","doc":"- **Job dependencies** — `depends_on` chains ensure jobs execute in order. Cycle detection prevents deadlocks.\n- **Batches** — Group jobs with completion callbacks. Batch state tracks completed/discarded counts.\n- **Unique jobs** — Prevent duplicates with configurable keys, states, time windows, debounce, and field replacement on conflict.\n- **Stale job rescue** — Heartbeat-based detection of zombie jobs with automatic rescheduling.\n- **Graceful shutdown** — Waits for in-flight jobs to finish before stopping.","ref":"readme.html#reliability"},{"type":"extras","title":"Resilience (seki integration) - Shigoto 仕事","doc":"- **Rate limiting** — Per-worker token bucket, sliding window, GCRA, or leaky bucket.\n- **Circuit breaking** — Auto-opens on repeated failures, configurable per worker.\n- **Bulkhead** — Per-worker concurrency limits (local node) and global concurrency limits (across nodes via PostgreSQL).\n- **Load shedding** — CoDel-based system-level protection, shedding low-priority jobs first.","ref":"readme.html#resilience-seki-integration"},{"type":"extras","title":"Operations - Shigoto 仕事","doc":"- **Encryption** — AES-256-GCM encryption for job args at rest with key rotation support.\n- **Middleware** — Composable before/after hooks for logging, metrics, authorization.\n- **Telemetry** — 16+ telemetry events covering job lifecycle, queue operations, resilience, batches, and cron.\n- **Health check** — `shigoto:health/0` reports pool status, job counts, stale jobs, and queue health.\n- **Bulk operations** — `insert_all/1`, `cancel_by/2`, `retry_by/2` for batch operations.\n- **Auto-archival** — Old jobs archived to `shigoto_jobs_archive` table, then pruned.\n- **Dashboard** — [shigoto_board](https://github.com/Taure/shigoto_board) provides a real-time web dashboard.","ref":"readme.html#operations"},{"type":"extras","title":"Testing - Shigoto 仕事","doc":"- **DB-free worker runner** — `perform_job/2,3` runs a worker through the real perform path (middleware + `deps_results`) with no database.\n- **Enqueue assertions** — `assert_enqueued/1,2`, `refute_enqueued/1`, `all_enqueued/0,1` in `shigoto_testing`.\n- **Testing modes** — `inline` (run on insert) / `manual` (capture without running), armed via a two-key confirmation so they can never silently activate in production.\n- **Synchronous drain** — `drain_queue/1` processes all jobs synchronously for integration tests.","ref":"readme.html#testing"},{"type":"extras","title":"Quick Start - Shigoto 仕事","doc":"Add to your deps:\n\n```erlang\n{deps, [\n    {shigoto, {git, \"https://github.com/Taure/shigoto.git\", {branch, \"main\"}}}\n]}.\n```\n\nConfigure in `sys.config`:\n\n```erlang\n{shigoto, [\n    {pool, my_app_db},\n    {queues, [{<<\"default\">>, 10}, {<<\"emails\">>, 5}]},\n    {poll_interval, 5000},\n    {cron, [\n        {<<\"daily_cleanup\">>, <<\"0 3 * * *\">>, my_cleanup_worker, #{}}\n    ]}\n]}\n```\n\nRun the migration:\n\n```erlang\nshigoto_migration:up(my_app_db).\n```\n\nDefine a worker:\n\n```erlang\n-module(my_email_worker).\n-behaviour(shigoto_worker).\n-export([perform/1]).\n\nperform(#{<<\"to\">> := To, <<\"subject\">> := Subject}) ->\n    send_email(To, Subject),\n    ok.\n```\n\nEnqueue jobs:\n\n```erlang\n%% Simple insert\nshigoto:insert(#{\n    worker => my_email_worker,\n    args => #{<<\"to\">> => <<\"user@example.com\">>, <<\"subject\">> => <<\"Welcome\">>}\n}).\n\n%% Scheduled for later\nshigoto:insert(#{\n    worker => my_cleanup_worker,\n    scheduled_at => {{2026, 3, 20}, {3, 0, 0}}\n}).\n\n%% With priority and queue\nshigoto:insert(#{\n    worker => my_urgent_worker,\n    args => #{},\n    priority => 10,\n    queue => <<\"critical\">>\n}).\n```","ref":"readme.html#quick-start"},{"type":"extras","title":"Job Lifecycle - Shigoto 仕事","doc":"```\navailable → executing → completed\n                     ↘ retryable → available (retry with backoff)\n                     ↘ discarded (max attempts reached)\n                     ↘ snoozed → available (rescheduled, attempt preserved)\n```\n\nJobs can also be `cancelled` via `shigoto:cancel/2` and retried via `shigoto:retry/2`.","ref":"readme.html#job-lifecycle"},{"type":"extras","title":"Worker Callbacks - Shigoto 仕事","doc":"All optional except `perform/1`:\n\n| Callback | Default | Description |\n|----------|---------|-------------|\n| `perform/1` | *required* | Execute the job. Return `ok`, `{error, Reason}`, or `{snooze, Seconds}` |\n| `max_attempts/0` | `3` | Maximum retry attempts before discarding |\n| `queue/0` | `<<\"default\">>` | Default queue name |\n| `priority/0` | `0` | Default priority (higher = claimed first) |\n| `timeout/0` | `300000` | Execution timeout in milliseconds |\n| `unique/0` | — | Uniqueness constraints |\n| `tags/0` | `[]` | Default tags for filtering |\n| `backoff/2` | exponential | Custom retry delay: `(Attempt, Error) -> Seconds` |\n| `rate_limit/0` | — | Seki rate limiter config |\n| `concurrency/0` | — | Max concurrent executions per node (seki bulkhead) |\n| `global_concurrency/0` | — | Max concurrent executions across all nodes |\n| `circuit_breaker/0` | — | Per-worker circuit breaker thresholds |\n| `middleware/0` | `[]` | Worker-specific middleware chain |\n| `on_discard/2` | — | Called when a job is permanently discarded |","ref":"readme.html#worker-callbacks"},{"type":"extras","title":"Configuration - Shigoto 仕事","doc":"| Option | Default | Description |\n|--------|---------|-------------|\n| `pool` | *required* | pgo pool name |\n| `queues` | `[{<<\"default\">>, 10}]` | Queue names and concurrency limits |\n| `poll_interval` | `5000` | Milliseconds between polling |\n| `cron` | `[]` | `{Name, Schedule, Worker, Args}` tuples |\n| `prune_after_days` | `14` | Days to keep completed/discarded jobs |\n| `shutdown_timeout` | `15000` | Milliseconds to wait for in-flight jobs |\n| `middleware` | `[]` | Global middleware chain |\n| `encryption_key` | — | 32-byte AES-256-GCM key |\n| `encryption_keys` | `[]` | Ordered key list for rotation (newest first) |\n| `heartbeat_interval` | `30000` | Stale job detection interval |\n| `load_shedding` | — | CoDel config map for seki |\n| `queue_weights` | `#{}` | Weighted polling distribution |\n| `fair_queues` | `[]` | Queues using partition-key fair claiming |\n| `notifier` | — | LISTEN/NOTIFY connection config |\n| `stage_interval` | `1000` | Milliseconds between due-job stager sweeps (needs `notifier`) |","ref":"readme.html#configuration"},{"type":"extras","title":"Supervision Tree - Shigoto 仕事","doc":"```\nshigoto_sup (one_for_one)\n  ├─ shigoto_executor_sup    — simple_one_for_one for job execution\n  ├─ shigoto_queue_sup       — one gen_server per queue\n  │    ├─ shigoto_queue:default\n  │    └─ shigoto_queue:emails\n  ├─ shigoto_cron            — cron scheduling with leader election\n  ├─ shigoto_pruner          — hourly archival and cleanup\n  ├─ shigoto_heartbeat       — periodic heartbeat updates\n  ├─ shigoto_notifier        — LISTEN/NOTIFY (optional)\n  └─ shigoto_stager          — surfaces newly-due jobs, leader election (optional)\n```","ref":"readme.html#supervision-tree"},{"type":"extras","title":"Guides - Shigoto 仕事","doc":"- [Getting Started](guides/getting-started.md)\n- [Workers](guides/workers.md)\n- [Cron Scheduling](guides/cron.md)\n- [Batches](guides/batches.md)\n- [Middleware](guides/middleware.md)\n- [Resilience](guides/resilience.md)\n- [Job Dependencies](guides/dependencies.md)\n- [Encryption](guides/encryption.md)\n- [Testing](guides/testing.md)","ref":"readme.html#guides"},{"type":"extras","title":"Ecosystem - Shigoto 仕事","doc":"- [shigoto_board](https://github.com/Taure/shigoto_board) — Real-time Arizona LiveView dashboard\n- [opentelemetry_shigoto](https://github.com/Taure/opentelemetry_shigoto) — OpenTelemetry instrumentation","ref":"readme.html#ecosystem"},{"type":"extras","title":"Requirements - Shigoto 仕事","doc":"- Erlang/OTP 27+\n- PostgreSQL 9.5+","ref":"readme.html#requirements"},{"type":"extras","title":"License - Shigoto 仕事","doc":"MIT","ref":"readme.html#license"},{"type":"extras","title":"Getting Started","doc":"# Getting Started","ref":"getting-started.html"},{"type":"extras","title":"Installation - Getting Started","doc":"","ref":"getting-started.html#installation"},{"type":"extras","title":"Erlang (rebar3) - Getting Started","doc":"Add `shigoto` to your `rebar.config` dependencies:\n\n```erlang\n{deps, [\n    {shigoto, {git, \"https://github.com/Taure/shigoto.git\", {branch, \"main\"}}}\n]}.\n```","ref":"getting-started.html#erlang-rebar3"},{"type":"extras","title":"Elixir (Mix) - Getting Started","doc":"Add `shigoto` to your `mix.exs`:\n\n```elixir\ndefp deps do\n  [\n    {:shigoto, github: \"Taure/shigoto\", branch: \"main\"}\n  ]\nend\n```","ref":"getting-started.html#elixir-mix"},{"type":"extras","title":"Configuration - Getting Started","doc":"","ref":"getting-started.html#configuration"},{"type":"extras","title":"Erlang (sys.config) - Getting Started","doc":"```erlang\n{shigoto, [\n    {pool, my_app_db},\n    {queues, [{<<\"default\">>, 10}, {<<\"mailers\">>, 5}]},\n    {poll_interval, 5000},\n    {prune_after_days, 14},\n    {shutdown_timeout, 15000},\n    {cron, []}\n]}\n```","ref":"getting-started.html#erlang-sys-config"},{"type":"extras","title":"Elixir (config.exs) - Getting Started","doc":"```elixir\nconfig :shigoto,\n  pool: :my_app_db,\n  queues: [{\"default\", 10}, {\"mailers\", 5}],\n  poll_interval: 5000,\n  prune_after_days: 14,\n  shutdown_timeout: 15000,\n  cron: []\n```","ref":"getting-started.html#elixir-config-exs"},{"type":"extras","title":"Configuration Reference - Getting Started","doc":"| Key | Default | Description |\n|-----|---------|-------------|\n| `pool` | *required* | Your pgo pool name |\n| `queues` | `[{<<\"default\">>, 10}]` | Queue names with concurrency limits |\n| `poll_interval` | `5000` | Milliseconds between polling for new jobs |\n| `prune_after_days` | `14` | Days before completed/discarded jobs are archived |\n| `shutdown_timeout` | `15000` | Milliseconds to wait for in-flight jobs during shutdown |\n| `cron` | `[]` | Cron entries (see the [Cron](cron.md) guide) |\n| `middleware` | `[]` | Global middleware chain (see [Middleware](middleware.md)) |\n| `encryption_key` | `undefined` | 32-byte AES-256-GCM key for encrypting job args |\n| `heartbeat_interval` | `30000` | Heartbeat interval in ms for executing jobs |\n| `load_shedding` | `undefined` | Seki load shedding config (see [Resilience](resilience.md)) |\n| `queue_weights` | `#{}` | Queue weight map for weighted polling |\n| `fair_queues` | `[]` | Queue names that use partition-key fair claiming |\n| `fanout_queues` | `[]` | Broadcast queues where all nodes process every job (see [Fanout Queues](fanout-queues.md)) |","ref":"getting-started.html#configuration-reference"},{"type":"extras","title":"Run the Migration - Getting Started","doc":"Create the necessary tables:\n\n```erlang\nshigoto_migration:up(my_app_db).\n```\n\n```elixir\n:shigoto_migration.up(:my_app_db)\n```","ref":"getting-started.html#run-the-migration"},{"type":"extras","title":"Create a Worker - Getting Started","doc":"","ref":"getting-started.html#create-a-worker"},{"type":"extras","title":"Erlang - Getting Started","doc":"```erlang\n-module(my_email_worker).\n-behaviour(shigoto_worker).\n-export([perform/1]).\n\nperform(#{<<\"to\">> := To, <<\"subject\">> := Subject, <<\"body\">> := Body}) ->\n    my_mailer:send(To, Subject, Body),\n    ok.\n```","ref":"getting-started.html#erlang"},{"type":"extras","title":"Elixir - Getting Started","doc":"```elixir\ndefmodule MyEmailWorker do\n  @behaviour :shigoto_worker\n\n  @impl true\n  def perform(%{\"to\" => to, \"subject\" => subject, \"body\" => body}) do\n    MyMailer.send(to, subject, body)\n    :ok\n  end\nend\n```\n\n> **Note:** Job args always have binary keys (`<<\"key\">>` / `\"key\"`) because\n> they are stored as JSONB in PostgreSQL.","ref":"getting-started.html#elixir"},{"type":"extras","title":"Insert a Job - Getting Started","doc":"","ref":"getting-started.html#insert-a-job"},{"type":"extras","title":"Erlang - Getting Started","doc":"```erlang\nshigoto:insert(#{\n    worker => my_email_worker,\n    args => #{<<\"to\">> => <<\"user@example.com\">>, <<\"subject\">> => <<\"Welcome\">>}\n}).\n```","ref":"getting-started.html#erlang-1"},{"type":"extras","title":"Elixir - Getting Started","doc":"```elixir\n:shigoto.insert(%{\n  worker: MyEmailWorker,\n  args: %{\"to\" => \"user@example.com\", \"subject\" => \"Welcome\"}\n})\n```\n\nWith options:\n\n```elixir\n:shigoto.insert(%{\n  worker: MyEmailWorker,\n  args: %{\"to\" => \"user@example.com\"},\n  queue: \"mailers\",\n  priority: 5,\n  max_attempts: 10,\n  tags: [\"email\", \"onboarding\"],\n  scheduled_at: {{2026, 3, 19}, {10, 0, 0}}\n})\n```","ref":"getting-started.html#elixir-1"},{"type":"extras","title":"Bulk Insert - Getting Started","doc":"Insert many jobs in a single SQL roundtrip:\n\n```erlang\nshigoto:insert_all([\n    #{worker => my_worker, args => #{<<\"id\">> => 1}},\n    #{worker => my_worker, args => #{<<\"id\">> => 2}},\n    #{worker => my_worker, args => #{<<\"id\">> => 3}}\n]).\n```\n\n```elixir\n:shigoto.insert_all([\n  %{worker: MyWorker, args: %{\"id\" => 1}},\n  %{worker: MyWorker, args: %{\"id\" => 2}},\n  %{worker: MyWorker, args: %{\"id\" => 3}}\n])\n```","ref":"getting-started.html#bulk-insert"},{"type":"extras","title":"Transactional Enqueue - Getting Started","doc":"If shigoto uses the same pgo pool as your application, job inserts participate in\nyour database transactions. The job is only enqueued if the transaction commits:\n\n```erlang\npgo:transaction(fun() ->\n    pgo:query(~\"INSERT INTO users (name, email) VALUES ($1, $2)\", [Name, Email]),\n    shigoto:insert(#{worker => welcome_email_worker, args => #{<<\"email\">> => Email}})\nend).\n```\n\nIf the transaction rolls back (e.g. a unique constraint violation on the user),\nthe job is never inserted. No \"user created but email lost\" or \"email sent but\nuser creation failed\" bugs.\n\nThis works with Kura too — just configure shigoto to use the same pool:\n\n```erlang\n{pgo, [{pools, [{default, #{...}}]}]},\n{shigoto, [{pool, default}]}\n```","ref":"getting-started.html#transactional-enqueue"},{"type":"extras","title":"Testing with drain_queue - Getting Started","doc":"Process all pending jobs synchronously in tests:\n\n```erlang\nshigoto:drain_queue(<<\"default\">>).\nshigoto:drain_queue(<<\"default\">>, #{timeout => 30000}).\n```\n\n```elixir\n:shigoto.drain_queue(\"default\")\n:shigoto.drain_queue(\"default\", %{timeout: 30000})\n```","ref":"getting-started.html#testing-with-drain_queue"},{"type":"extras","title":"Next Steps - Getting Started","doc":"- [Workers](workers.md) — Error handling, retries, backoff, timeouts, and optional callbacks\n- [Cron](cron.md) — Scheduled recurring jobs\n- [Batches](batches.md) — Group jobs with completion callbacks\n- [Middleware](middleware.md) — Before/after hooks for job execution\n- [Fanout Queues](fanout-queues.md) — Broadcast delivery to all nodes (cloud-native pub/sub)\n- [Resilience](resilience.md) — Rate limiting, circuit breaking, and load shedding via seki","ref":"getting-started.html#next-steps"},{"type":"extras","title":"Workers","doc":"# Workers","ref":"workers.html"},{"type":"extras","title":"The shigoto_worker Behaviour - Workers","doc":"Every worker implements the `shigoto_worker` behaviour. The only required\ncallback is `perform/1`:\n\n```erlang\n-callback perform(Args :: map()) -> ok | {error, term()} | {snooze, pos_integer()}.\n```","ref":"workers.html#the-shigoto_worker-behaviour"},{"type":"extras","title":"Basic Worker - Workers","doc":"","ref":"workers.html#basic-worker"},{"type":"extras","title":"Erlang - Workers","doc":"```erlang\n-module(notification_worker).\n-behaviour(shigoto_worker).\n-export([perform/1]).\n\nperform(#{<<\"user_id\">> := UserId, <<\"message\">> := Message}) ->\n    send_push_notification(UserId, Message),\n    ok.\n```","ref":"workers.html#erlang"},{"type":"extras","title":"Elixir - Workers","doc":"```elixir\ndefmodule NotificationWorker do\n  @behaviour :shigoto_worker\n\n  @impl true\n  def perform(%{\"user_id\" => user_id, \"message\" => message}) do\n    send_push_notification(user_id, message)\n    :ok\n  end\nend\n```","ref":"workers.html#elixir"},{"type":"extras","title":"Args Format - Workers","doc":"Job args are stored as JSONB in PostgreSQL. They always arrive as a map with\n**binary keys**:\n\n```erlang\n%% Insert with binary keys\nshigoto:insert(#{worker => my_worker, args => #{<<\"count\">> => 42}}).\n\n%% In perform/1: #{<<\"count\">> => 42}\n```\n\n```elixir\n# Elixir string keys work directly\n:shigoto.insert(%{worker: MyWorker, args: %{\"count\" => 42}})\n\n# In perform/1: %{\"count\" => 42}\n```","ref":"workers.html#args-format"},{"type":"extras","title":"Return Values - Workers","doc":"| Return | Effect |\n|--------|--------|\n| `ok` | Job marked as completed |\n| `{error, Reason}` | Job failed, retried with backoff if attempts remain |\n| `{snooze, Seconds}` | Job rescheduled for later without counting as a failure |\n\nExceptions (throw, error, exit) are treated as failures.","ref":"workers.html#return-values"},{"type":"extras","title":"Optional Callbacks - Workers","doc":"Workers can export optional callbacks to configure defaults:\n\n| Callback | Default | Description |\n|----------|---------|-------------|\n| `max_attempts/0` | `3` | Maximum retry attempts |\n| `queue/0` | `<<\"default\">>` | Default queue name |\n| `priority/0` | `0` | Default priority (higher = claimed first) |\n| `timeout/0` | `300000` | Execution timeout in milliseconds |\n| `unique/0` | none | Uniqueness constraints |\n| `tags/0` | `[]` | Default tags for this worker |\n| `backoff/2` | exponential | Custom backoff strategy |\n| `rate_limit/0` | none | Per-worker rate limiting via seki |\n| `concurrency/0` | none | Max concurrent executions across all queues |\n| `middleware/0` | `[]` | Worker-specific middleware list |\n| `on_discard/2` | none | Called when a job is permanently discarded |","ref":"workers.html#optional-callbacks"},{"type":"extras","title":"Erlang Example - Workers","doc":"```erlang\n-module(api_sync_worker).\n-behaviour(shigoto_worker).\n-export([perform/1, max_attempts/0, queue/0, priority/0, timeout/0, tags/0]).\n\nperform(#{<<\"endpoint\">> := Endpoint}) ->\n    case httpc:request(binary_to_list(Endpoint)) of\n        {ok, _} -> ok;\n        {error, Reason} -> {error, Reason}\n    end.\n\nmax_attempts() -> 5.\nqueue() -> <<\"api\">>.\npriority() -> 3.\ntimeout() -> 60000.\ntags() -> [<<\"api\">>, <<\"sync\">>].\n```","ref":"workers.html#erlang-example"},{"type":"extras","title":"Elixir Example - Workers","doc":"```elixir\ndefmodule ApiSyncWorker do\n  @behaviour :shigoto_worker\n\n  @impl true\n  def perform(%{\"endpoint\" => endpoint}) do\n    case HTTPoison.get(endpoint) do\n      {:ok, %{status_code: 200}} -> :ok\n      {:error, reason} -> {:error, reason}\n    end\n  end\n\n  def max_attempts, do: 5\n  def queue, do: \"api\"\n  def priority, do: 3\n  def timeout, do: 60_000\n  def tags, do: [\"api\", \"sync\"]\nend\n```","ref":"workers.html#elixir-example"},{"type":"extras","title":"Custom Backoff - Workers","doc":"Override the default exponential backoff (`min(attempt^4 + rand(0..30), 1800)`):\n\n```erlang\n-module(gentle_worker).\n-behaviour(shigoto_worker).\n-export([perform/1, backoff/2]).\n\nperform(_Args) -> {error, try_later}.\n\n%% Linear backoff: 10 seconds per attempt, max 5 minutes\nbackoff(Attempt, _Error) ->\n    min(Attempt * 10, 300).\n```\n\n```elixir\ndefmodule GentleWorker do\n  @behaviour :shigoto_worker\n\n  @impl true\n  def perform(_args), do: {:error, :try_later}\n\n  def backoff(attempt, _error), do: min(attempt * 10, 300)\nend\n```","ref":"workers.html#custom-backoff"},{"type":"extras","title":"on_discard Callback - Workers","doc":"Called when a job exhausts all attempts and is permanently discarded:\n\n```erlang\n-module(critical_worker).\n-behaviour(shigoto_worker).\n-export([perform/1, on_discard/2]).\n\nperform(_Args) -> {error, still_broken}.\n\non_discard(Args, Errors) ->\n    logger:error(\"critical job discarded\", #{args => Args, errors => Errors}),\n    alert_ops_team(Args).\n```","ref":"workers.html#on_discard-callback"},{"type":"extras","title":"Snoozing Jobs - Workers","doc":"Return `{snooze, Seconds}` to reschedule a job without counting as a failure:\n\n```erlang\nperform(#{<<\"api_key\">> := Key}) ->\n    case check_rate_limit(Key) of\n        ok -> do_work(Key);\n        rate_limited -> {snooze, 60}  %% Try again in 60 seconds\n    end.\n```","ref":"workers.html#snoozing-jobs"},{"type":"extras","title":"Unique Jobs - Workers","doc":"Prevent duplicate jobs via the `unique/0` callback or per-insert options:\n\n```erlang\nunique() ->\n    #{\n        keys => [worker, args],         %% Fields to check\n        states => [available, executing, retryable],  %% States to check against\n        period => 300,                  %% Seconds (or infinity)\n        replace => [priority],          %% Fields to update on conflict\n        debounce => 5                   %% Reset scheduled_at on conflict (seconds)\n    }.\n```\n\nThe `debounce` option is useful for \"run N seconds after the *last* trigger\":\n\n```erlang\n%% Each call resets the timer to 5 seconds from now\nshigoto:insert(\n    #{worker => search_indexer, args => #{<<\"table\">> => <<\"users\">>}},\n    #{unique => #{keys => [worker, args], debounce => 5}}\n).\n```","ref":"workers.html#unique-jobs"},{"type":"extras","title":"Tags - Workers","doc":"Tag jobs for filtering and bulk operations:\n\n```erlang\n%% Via worker callback\ntags() -> [<<\"email\">>, <<\"marketing\">>].\n\n%% Via insert params\nshigoto:insert(#{worker => my_worker, args => #{}, tags => [<<\"urgent\">>]}).\n\n%% Cancel by tag\nshigoto:cancel_by(my_pool, #{tags => [<<\"marketing\">>]}).\n```","ref":"workers.html#tags"},{"type":"extras","title":"Progress Tracking - Workers","doc":"Report progress from within `perform/1`:\n\n```erlang\nperform(#{<<\"job_id\">> := JobId, <<\"items\">> := Items}) ->\n    Total = length(Items),\n    lists:foldl(\n        fun(Item, Idx) ->\n            process(Item),\n            shigoto:report_progress(JobId, (Idx * 100) div Total),\n            Idx + 1\n        end,\n        1,\n        Items\n    ),\n    ok.\n```","ref":"workers.html#progress-tracking"},{"type":"extras","title":"Job Dependencies - Workers","doc":"Jobs can depend on other jobs completing first:\n\n```erlang\n{ok, Job1} = shigoto:insert(#{worker => step_one, args => #{}}),\n{ok, Job2} = shigoto:insert(#{worker => step_two, args => #{}}),\nJob1Id = maps:get(id, Job1),\nJob2Id = maps:get(id, Job2),\n\n%% This job won't run until Job1 and Job2 complete\nshigoto:insert(#{\n    worker => final_step,\n    args => #{},\n    depends_on => [Job1Id, Job2Id]\n}).\n```","ref":"workers.html#job-dependencies"},{"type":"extras","title":"Partitioned Queues - Workers","doc":"For multi-tenant fairness, set a `partition_key` so no single tenant starves others:\n\n```erlang\nshigoto:insert(#{\n    worker => tenant_sync,\n    args => #{<<\"tenant_id\">> => <<\"acme\">>},\n    partition_key => <<\"acme\">>\n}).\n```\n\nUse `shigoto_repo:claim_jobs_fair/3` for round-robin partition claiming.","ref":"workers.html#partitioned-queues"},{"type":"extras","title":"Cron Scheduling","doc":"# Cron Scheduling\n\nShigoto includes a built-in cron scheduler that checks configured entries every\nminute and inserts jobs for matching schedules. On startup, it catches up on\nany intervals missed while the node was down (up to 60 missed minutes).","ref":"cron.html"},{"type":"extras","title":"Configuration - Cron Scheduling","doc":"","ref":"cron.html#configuration"},{"type":"extras","title":"Erlang (sys.config) - Cron Scheduling","doc":"```erlang\n{shigoto, [\n    {pool, my_app_db},\n    {cron, [\n        {<<\"daily_cleanup\">>, <<\"0 2 * * *\">>, cleanup_worker, #{<<\"days\">> => 30}},\n        {<<\"hourly_sync\">>, <<\"0 * * * *\">>, sync_worker, #{}},\n        {<<\"weekday_report\">>, <<\"30 9 * * 1-5\">>, report_worker, #{}}\n    ]}\n]}\n```","ref":"cron.html#erlang-sys-config"},{"type":"extras","title":"Elixir (config.exs) - Cron Scheduling","doc":"```elixir\nconfig :shigoto,\n  pool: :my_app_db,\n  cron: [\n    {\"daily_cleanup\", \"0 2 * * *\", :cleanup_worker, %{\"days\" => 30}},\n    {\"hourly_sync\", \"0 * * * *\", :sync_worker, %{}},\n    {\"weekday_report\", \"30 9 * * 1-5\", ReportWorker, %{}}\n  ]\n```\n\nEach cron entry is a 4-tuple `{Name, Schedule, Worker, Args}` or a 5-tuple\n`{Name, Schedule, Worker, Args, Opts}` where `Opts` is a map.\n\n| Field | Type | Description |\n|-------|------|-------------|\n| Name | binary | Unique identifier |\n| Schedule | binary | 5-field cron expression |\n| Worker | module | Worker implementing `shigoto_worker` |\n| Args | map | Args map passed to `perform/1` |\n| Opts | map | Optional. Supports `timezone` (see below) |","ref":"cron.html#elixir-config-exs"},{"type":"extras","title":"Timezones - Cron Scheduling","doc":"By default schedules are matched against UTC. Set a `timezone` in the entry's\n`Opts` map to match against a local wall-clock time instead:\n\n```erlang\n{cron, [\n    %% 09:00 Stockholm time, DST-aware, every weekday\n    {<<\"morning_report\">>, <<\"0 9 * * 1-5\">>, report_worker, #{},\n        #{timezone => <<\"Europe/Stockholm\">>}},\n    %% fixed offset, no DST\n    {<<\"utc_plus_2\">>, <<\"0 3 * * *\">>, sync_worker, #{}, #{timezone => 2}}\n]}\n```\n\n`timezone` accepts:\n\n| Value | Example | DST |\n|-------|---------|-----|\n| `utc` (default) | `utc` | n/a |\n| integer hour offset | `2`, `-5` | no |\n| `\"+/-N\"` or `\"UTC\"` binary | `<<\"+2\">>` | no |\n| named IANA zone | `<<\"Europe/Stockholm\">>` | yes |\n\nNamed IANA zones are resolved against the operating system's time zone database\n(`$TZDIR` or `/usr/share/zoneinfo`) for each instant, so daylight-saving\ntransitions are handled automatically. If a named zone cannot be resolved the\nentry falls back to UTC and a warning is logged.","ref":"cron.html#timezones"},{"type":"extras","title":"Cron Expression Syntax - Cron Scheduling","doc":"Standard 5-field format: `minute hour day-of-month month day-of-week`\n\n```\n┌───────────── minute (0-59)\n│ ┌───────────── hour (0-23)\n│ │ ┌───────────── day of month (1-31)\n│ │ │ ┌───────────── month (1-12)\n│ │ │ │ ┌───────────── day of week (0-6, Sunday=0)\n│ │ │ │ │\n* * * * *\n```\n\n| Syntax | Description | Example |\n|--------|-------------|---------|\n| `*` | Any value | `* * * * *` (every minute) |\n| `N` | Exact value | `30 * * * *` (at minute 30) |\n| `N-M` | Range | `0 9-17 * * *` (hours 9 through 17) |\n| `*/N` | Step | `*/15 * * * *` (every 15 minutes) |\n| `N-M/S` | Step within range | `0-30/10 * * * *` (minutes 0, 10, 20, 30) |\n| `N,M,O` | List | `0,15,30,45 * * * *` (specific minutes) |","ref":"cron.html#cron-expression-syntax"},{"type":"extras","title":"Missed Cron Catch-Up - Cron Scheduling","doc":"When the cron scheduler starts, it checks the `last_scheduled_at` for each\nentry in the database. If any intervals were missed (e.g., the node was down),\nit inserts jobs for up to 60 missed minutes. Jobs are deduplicated via unique\nconstraints to prevent double-execution.","ref":"cron.html#missed-cron-catch-up"},{"type":"extras","title":"How It Works - Cron Scheduling","doc":"1. `shigoto_cron` gen_server checks all entries once per minute\n2. Matching entries trigger a job insert into the `default` queue\n3. Jobs use a 60-second unique constraint to prevent duplicates\n4. Cron jobs follow the same retry, backoff, and pruning rules as regular jobs","ref":"cron.html#how-it-works"},{"type":"extras","title":"Timezone notes - Cron Scheduling","doc":"Named zones resolve against the operating system's IANA database\n(`/usr/share/zoneinfo`), so every node in a cluster should run a consistent\n`tzdata` version. A zone that cannot be resolved (missing or corrupt tzdata)\nfalls back to UTC with a logged warning rather than failing.\n\nCron matches at minute granularity under at-least-once semantics: on a DST\nfall-back the repeated wall-clock minute may match twice (unique-job de-dup\nwithin the 60s window prevents a duplicate enqueue), and on a spring-forward the\nskipped minute does not match. Schedule around 03:00 local to avoid the DST\nwindow if exact-once firing at those minutes matters.","ref":"cron.html#timezone-notes"},{"type":"extras","title":"Batches","doc":"# Batches\n\nBatches group jobs together with completion callbacks. When all jobs in a\nbatch finish, a callback worker is automatically invoked.","ref":"batches.html"},{"type":"extras","title":"Creating a Batch - Batches","doc":"","ref":"batches.html#creating-a-batch"},{"type":"extras","title":"Erlang - Batches","doc":"```erlang\n{ok, Batch} = shigoto:new_batch(#{\n    callback_worker => my_batch_callback,\n    callback_args => #{<<\"report_id\">> => 42}\n}),\nBatchId = maps:get(id, Batch),\n\n%% Add jobs to the batch\nshigoto:insert(#{worker => step_one, args => #{<<\"n\">> => 1}, batch => BatchId}),\nshigoto:insert(#{worker => step_two, args => #{<<\"n\">> => 2}, batch => BatchId}).\n```","ref":"batches.html#erlang"},{"type":"extras","title":"Elixir - Batches","doc":"```elixir\n{:ok, batch} = :shigoto.new_batch(%{\n  callback_worker: MyBatchCallback,\n  callback_args: %{\"report_id\" => 42}\n})\nbatch_id = batch.id\n\n:shigoto.insert(%{worker: StepOne, args: %{\"n\" => 1}, batch: batch_id})\n:shigoto.insert(%{worker: StepTwo, args: %{\"n\" => 2}, batch: batch_id})\n```","ref":"batches.html#elixir"},{"type":"extras","title":"Batch Callbacks - Batches","doc":"When all jobs complete, the callback worker receives the `callback_args`:\n\n```erlang\n-module(my_batch_callback).\n-behaviour(shigoto_worker).\n-export([perform/1]).\n\nperform(#{<<\"report_id\">> := ReportId}) ->\n    generate_report(ReportId),\n    ok.\n```\n\nIf any job is discarded, the callback receives an extra `<<\"_batch_event\">> => <<\"discard\">>` key.","ref":"batches.html#batch-callbacks"},{"type":"extras","title":"Batch States - Batches","doc":"| State | Description |\n|-------|-------------|\n| `active` | Jobs are still processing |\n| `callback_completing` | All jobs done, callback inserted |\n| `callback_discarding` | Some jobs discarded, callback inserted |\n| `finished` | Batch complete (no callback configured) |","ref":"batches.html#batch-states"},{"type":"extras","title":"Monitoring Batches - Batches","doc":"```erlang\n{ok, Batch} = shigoto:get_batch(BatchId).\n%% #{total_jobs => 10, completed_jobs => 7, discarded_jobs => 1, state => <<\"active\">>}\n```","ref":"batches.html#monitoring-batches"},{"type":"extras","title":"Bulk Insert into Batches - Batches","doc":"```erlang\n{ok, Batch} = shigoto:new_batch(#{callback_worker => report_worker}),\nBatchId = maps:get(id, Batch),\nshigoto:insert_all([\n    #{worker => process_item, args => #{<<\"id\">> => I}, batch => BatchId}\n || I <- lists:seq(1, 1000)\n]).\n```","ref":"batches.html#bulk-insert-into-batches"},{"type":"extras","title":"Job Dependencies","doc":"# Job Dependencies\n\nJobs can declare dependencies on other jobs using `depends_on`. A dependent\njob stays in `available` state but won't be claimed until all its dependencies\nhave completed, been discarded, or been cancelled.","ref":"dependencies.html"},{"type":"extras","title":"Basic Usage - Job Dependencies","doc":"```erlang\n{ok, Step1} = shigoto:insert(#{\n    worker => extract_worker,\n    args => #{<<\"source\">> => <<\"s3://bucket/data.csv\">>}\n}),\n\n{ok, Step2} = shigoto:insert(#{\n    worker => transform_worker,\n    args => #{<<\"format\">> => <<\"parquet\">>},\n    depends_on => [maps:get(id, Step1)]\n}),\n\n{ok, _Step3} = shigoto:insert(#{\n    worker => load_worker,\n    args => #{<<\"table\">> => <<\"results\">>},\n    depends_on => [maps:get(id, Step2)]\n}).\n```\n\nStep2 won't execute until Step1 completes. Step3 won't execute until Step2\ncompletes. This creates an ETL pipeline that executes in order.","ref":"dependencies.html#basic-usage"},{"type":"extras","title":"Fan-in (Multiple Parents) - Job Dependencies","doc":"A job can depend on multiple parent jobs:\n\n```erlang\n{ok, A} = shigoto:insert(#{worker => fetch_api_a, args => #{}}),\n{ok, B} = shigoto:insert(#{worker => fetch_api_b, args => #{}}),\n{ok, C} = shigoto:insert(#{worker => fetch_api_c, args => #{}}),\n\n{ok, _Merge} = shigoto:insert(#{\n    worker => merge_results,\n    args => #{},\n    depends_on => [maps:get(id, A), maps:get(id, B), maps:get(id, C)]\n}).\n```\n\nThe merge job only runs after all three fetch jobs finish.","ref":"dependencies.html#fan-in-multiple-parents"},{"type":"extras","title":"Dependency Resolution - Job Dependencies","doc":"When a job completes, gets discarded, or gets cancelled, shigoto automatically\nremoves its ID from all `depends_on` arrays. Once a job's `depends_on` array\nis empty, it becomes claimable.\n\nThis means dependent jobs aren't permanently stuck if a parent fails — they\nstill execute after the parent reaches a terminal state.","ref":"dependencies.html#dependency-resolution"},{"type":"extras","title":"Cycle Detection - Job Dependencies","doc":"Shigoto validates dependencies on insert:\n\n- **Missing IDs**: Returns `{error, {missing_dependencies, [Id, ...]}}` if\n  any dependency ID doesn't exist.\n- **Cycles**: Returns `{error, dependency_cycle}` if the new job's dependencies\n  would create a circular dependency (e.g., A depends on B, B depends on A).\n\n```erlang\n%% This would fail with {error, dependency_cycle}\n{ok, X} = shigoto:insert(#{worker => w, args => #{}}),\n{ok, Y} = shigoto:insert(#{worker => w, args => #{}, depends_on => [maps:get(id, X)]}),\n{error, dependency_cycle} = shigoto:insert(#{\n    worker => w,\n    args => #{},\n    depends_on => [maps:get(id, X), maps:get(id, Y)]\n}).\n```","ref":"dependencies.html#cycle-detection"},{"type":"extras","title":"Combining with Batches - Job Dependencies","doc":"Dependencies work well with batches for complex workflows:\n\n```erlang\n{ok, Batch} = shigoto:new_batch(#{\n    callback_worker => pipeline_complete,\n    callback_args => #{<<\"pipeline\">> => <<\"etl_daily\">>}\n}),\nBatchId = maps:get(id, Batch),\n\n{ok, Extract} = shigoto:insert(#{\n    worker => extract_worker, args => #{}, batch => BatchId\n}),\n{ok, _Transform} = shigoto:insert(#{\n    worker => transform_worker, args => #{},\n    batch => BatchId,\n    depends_on => [maps:get(id, Extract)]\n}).\n```","ref":"dependencies.html#combining-with-batches"},{"type":"extras","title":"Middleware","doc":"# Middleware\n\nMiddleware wraps job execution with before/after logic. Each middleware is a\nfunction that receives the job map and a `Next` function.","ref":"middleware.html"},{"type":"extras","title":"Writing Middleware - Middleware","doc":"","ref":"middleware.html#writing-middleware"},{"type":"extras","title":"Erlang - Middleware","doc":"```erlang\nmy_logging_middleware(Job, Next) ->\n    JobId = maps:get(id, Job),\n    logger:info(\"starting job ~p\", [JobId]),\n    Result = Next(),\n    logger:info(\"finished job ~p: ~p\", [JobId, Result]),\n    Result.\n```","ref":"middleware.html#erlang"},{"type":"extras","title":"Elixir - Middleware","doc":"```elixir\ndef my_logging_middleware(job, next) do\n  job_id = job.id\n  Logger.info(\"starting job #{job_id}\")\n  result = next.()\n  Logger.info(\"finished job #{job_id}: #{inspect(result)}\")\n  result\nend\n```","ref":"middleware.html#elixir"},{"type":"extras","title":"Global Middleware - Middleware","doc":"Applied to all jobs via configuration:\n\n```erlang\n{shigoto, [\n    {middleware, [fun my_app_middleware:timing/2, fun my_app_middleware:tracing/2]}\n]}\n```\n\n```elixir\nconfig :shigoto,\n  middleware: [&MyAppMiddleware.timing/2, &MyAppMiddleware.tracing/2]\n```","ref":"middleware.html#global-middleware"},{"type":"extras","title":"Worker Middleware - Middleware","doc":"Workers can define their own middleware via the `middleware/0` callback:\n\n```erlang\n-module(audited_worker).\n-behaviour(shigoto_worker).\n-export([perform/1, middleware/0]).\n\nperform(Args) -> do_work(Args).\n\nmiddleware() ->\n    [fun audit_middleware/2].\n\naudit_middleware(Job, Next) ->\n    audit_log:record(started, Job),\n    Result = Next(),\n    audit_log:record(finished, Job),\n    Result.\n```","ref":"middleware.html#worker-middleware"},{"type":"extras","title":"Execution Order - Middleware","doc":"Middleware runs in this order:\n\n1. Global middleware (from config, in order)\n2. Worker middleware (from `middleware/0` callback, in order)\n3. `Worker:perform/1`","ref":"middleware.html#execution-order"},{"type":"extras","title":"Short-Circuiting - Middleware","doc":"Return early without calling `Next()` to skip execution:\n\n```erlang\nmaintenance_gate(Job, Next) ->\n    case application:get_env(my_app, maintenance_mode, false) of\n        true -> {snooze, 300};  %% Snooze for 5 minutes\n        false -> Next()\n    end.\n```","ref":"middleware.html#short-circuiting"},{"type":"extras","title":"Built-in Resilience - Middleware","doc":"Seki resilience checks (rate limiting, circuit breaking, bulkhead, load\nshedding) run *before* the middleware chain. See [Resilience](resilience.md).","ref":"middleware.html#built-in-resilience"},{"type":"extras","title":"Fanout Queues","doc":"# Fanout Queues\n\nStandard Shigoto queues are single-consumer: one node claims each job via\n`FOR UPDATE SKIP LOCKED`. Fanout queues are multi-consumer: **every node\nprocesses every job**.","ref":"fanout-queues.html"},{"type":"extras","title":"When to use - Fanout Queues","doc":"Fanout queues are for broadcast events that need to reach all connected\nclients, regardless of which node they're on:\n\n- Session revocation (ban, token expiry)\n- Push notifications to connected WebSocket sessions\n- Cross-node chat message delivery\n- Presence updates\n\nThey replace the need for Redis pub/sub, NATS, or distributed Erlang in\ncloud-native deployments. The only infrastructure required is PostgreSQL.","ref":"fanout-queues.html#when-to-use"},{"type":"extras","title":"How it works - Fanout Queues","doc":"Each node polls the `shigoto_jobs` table for recent jobs on fanout queues\nusing a time window (default 120 seconds). Unlike standard queues, there\nis no row locking — all nodes read the same rows.\n\nEach node tracks which job IDs it has already processed in a local ETS\ntable. On node restart, the ETS is empty, so recent jobs within the window\nare re-processed. **Workers must be idempotent.**\n\n```\nProducer Node                 PostgreSQL              All Consumer Nodes\n     |                            |                         |\n     |-- shigoto:insert(...) ---->|                         |\n     |                            |-- poll (no locking) --->|\n     |                            |                         |-- ETS dedup\n     |                            |                         |-- execute locally\n     |                            |                         |\n     |                            |-- cleanup (2x window) --|\n```","ref":"fanout-queues.html#how-it-works"},{"type":"extras","title":"Configuration - Fanout Queues","doc":"","ref":"fanout-queues.html#configuration"},{"type":"extras","title":"Erlang (sys.config) - Fanout Queues","doc":"```erlang\n{shigoto, [\n    {pool, my_app_db},\n    {queues, [{<<\"default\">>, 10}]},\n    {fanout_queues, [\n        {<<\"broadcast\">>, 5, #{window => 120}}\n    ]},\n    {poll_interval, 500}\n]}\n```","ref":"fanout-queues.html#erlang-sys-config"},{"type":"extras","title":"Elixir (config.exs) - Fanout Queues","doc":"```elixir\nconfig :shigoto,\n  pool: :my_app_db,\n  queues: [{\"default\", 10}],\n  fanout_queues: [\n    {\"broadcast\", 5, %{window: 120}}\n  ],\n  poll_interval: 500\n```","ref":"fanout-queues.html#elixir-config-exs"},{"type":"extras","title":"Options - Fanout Queues","doc":"| Option | Default | Description |\n|--------|---------|-------------|\n| `window` | 120 | Time window in seconds. Jobs older than this are ignored. |\n\nThe second element is concurrency — how many jobs this node can process\nsimultaneously from this fanout queue.","ref":"fanout-queues.html#options"},{"type":"extras","title":"Writing a fanout worker - Fanout Queues","doc":"Fanout workers are regular `shigoto_worker` implementations. The only\nrequirement is that `perform/1` must be idempotent.\n\n```erlang\n-module(my_broadcast_worker).\n-behaviour(shigoto_worker).\n\n-export([perform/1, queue/0, max_attempts/1]).\n\nqueue() -> <<\"broadcast\">>.\n\nmax_attempts(_Args) -> 1.\n\nperform(#{type := <<\"session_revoked\">>, player_id := PlayerId, reason := Reason}) ->\n    %% Local delivery — only reaches sessions on THIS node\n    my_presence:disconnect(PlayerId, Reason);\nperform(#{type := <<\"notification\">>, player_id := PlayerId} = Payload) ->\n    my_presence:send(PlayerId, {notification, maps:without([type, player_id], Payload)}).\n```","ref":"fanout-queues.html#writing-a-fanout-worker"},{"type":"extras","title":"Enqueuing broadcast jobs - Fanout Queues","doc":"Use the standard `shigoto:insert/1` API. The job goes to PostgreSQL and\nall nodes pick it up on their next poll cycle.\n\n```erlang\nshigoto:insert(#{\n    worker => my_broadcast_worker,\n    args => #{\n        type => <<\"session_revoked\">>,\n        player_id => PlayerId,\n        reason => <<\"banned\">>\n    }\n}).\n```\n\nSet high priority to ensure broadcast jobs are processed before regular\nqueue jobs within the same poll cycle:\n\n```erlang\nshigoto:insert(#{\n    worker => my_broadcast_worker,\n    args => #{type => <<\"session_revoked\">>, player_id => PlayerId},\n    priority => 100\n}).\n```","ref":"fanout-queues.html#enqueuing-broadcast-jobs"},{"type":"extras","title":"Cleanup - Fanout Queues","doc":"Fanout jobs stay in `available` state since no node claims them. The\nfanout queue process automatically deletes jobs older than `2 x window`\nto prevent unbounded table growth. The ETS dedup set is also cleared\nperiodically if it exceeds 10,000 entries.","ref":"fanout-queues.html#cleanup"},{"type":"extras","title":"Design trade-offs - Fanout Queues","doc":"| Aspect | Standard Queue | Fanout Queue |\n|--------|---------------|--------------|\n| Delivery | Exactly once (one node) | At-least once (all nodes) |\n| Idempotency | Nice to have | Required |\n| Node restart | Picks up from last claimed ID | Re-processes recent window |\n| Job state | `available` -> `executing` -> `completed` | Stays `available` until pruned |\n| Locking | `FOR UPDATE SKIP LOCKED` | None |\n| Use case | Background work | Broadcast events |","ref":"fanout-queues.html#design-trade-offs"},{"type":"extras","title":"What NOT to use fanout for - Fanout Queues","doc":"- **High-frequency events** (>10/sec) — the poll interval adds latency\n  and the query load scales with job count in the window.\n- **Large payloads** — every node reads every job. Keep args small.\n- **Events that need exactly-once delivery** — use standard queues instead.\n- **Real-time game state** (10Hz tick loops) — use local `pg` with sticky\n  session placement. Fanout is for low-frequency cross-node events.","ref":"fanout-queues.html#what-not-to-use-fanout-for"},{"type":"extras","title":"Resilience","doc":"# Resilience\n\nShigoto integrates with [seki](https://github.com/Taure/seki) to provide\nper-worker rate limiting, circuit breaking, bulkhead (concurrency limiting),\nand system-level load shedding. All primitives are lazily initialized on\nfirst use.\n\nWhen seki is not running, all resilience checks are no-ops.","ref":"resilience.html"},{"type":"extras","title":"Rate Limiting - Resilience","doc":"Limit how fast a worker's jobs are executed. Seki provides four algorithms:\ntoken bucket, sliding window, GCRA, and leaky bucket.","ref":"resilience.html#rate-limiting"},{"type":"extras","title":"Erlang - Resilience","doc":"```erlang\n-module(api_worker).\n-behaviour(shigoto_worker).\n-export([perform/1, rate_limit/0]).\n\nperform(Args) -> call_external_api(Args).\n\nrate_limit() ->\n    #{\n        limit => 100,              %% 100 requests\n        window => 60000,           %% per minute\n        algorithm => sliding_window %% or: token_bucket, gcra, leaky_bucket\n    }.\n```","ref":"resilience.html#erlang"},{"type":"extras","title":"Elixir - Resilience","doc":"```elixir\ndefmodule ApiWorker do\n  @behaviour :shigoto_worker\n\n  @impl true\n  def perform(args), do: call_external_api(args)\n\n  def rate_limit do\n    %{limit: 100, window: 60_000, algorithm: :sliding_window}\n  end\nend\n```\n\nWhen the rate limit is hit, jobs are **snoozed** (not retried), preserving\nthe attempt count.","ref":"resilience.html#elixir"},{"type":"extras","title":"Circuit Breaking - Resilience","doc":"Every worker automatically gets a circuit breaker. When a worker fails\nrepeatedly (50% failure rate over 20 calls), the breaker opens and subsequent\njobs are snoozed for 10 seconds until the breaker transitions to half-open.\n\nThis prevents burning through retry attempts against a known-broken dependency.\n\nThe circuit breaker is configured with sensible defaults:\n- Window: 20 calls (count-based)\n- Failure threshold: 50%\n- Wait duration: 30 seconds before half-open\n- Half-open requests: 3","ref":"resilience.html#circuit-breaking"},{"type":"extras","title":"Bulkhead (Concurrency Limiting) - Resilience","doc":"Limit how many instances of a worker can execute concurrently across all queues\nand nodes:\n\n```erlang\n-module(heavy_worker).\n-behaviour(shigoto_worker).\n-export([perform/1, concurrency/0]).\n\nperform(Args) -> heavy_computation(Args).\n\nconcurrency() -> 5.  %% Max 5 concurrent executions\n```\n\n```elixir\ndefmodule HeavyWorker do\n  @behaviour :shigoto_worker\n\n  @impl true\n  def perform(args), do: heavy_computation(args)\n\n  def concurrency, do: 5\nend\n```\n\nWhen the bulkhead is full, jobs are snoozed for 5 seconds.","ref":"resilience.html#bulkhead-concurrency-limiting"},{"type":"extras","title":"Load Shedding - Resilience","doc":"System-level CoDel-based load shedding protects the entire job system from\noverload. Enable via configuration:\n\n```erlang\n{shigoto, [\n    {load_shedding, #{\n        target => 5,           %% CoDel target sojourn time (ms)\n        interval => 100,       %% CoDel interval (ms)\n        max_in_flight => 1000  %% Max concurrent jobs system-wide\n    }}\n]}\n```\n\nLow-priority jobs are shed first. Shigoto maps job priorities to seki levels:\n\n| Job Priority | Seki Level | Behavior |\n|-------------|-----------|----------|\n| >= 10 | 0 (critical) | Last to be shed |\n| 5-9 | 1 (high) | |\n| 0-4 | 2 (normal) | |\n| < 0 | 3 (low) | First to be shed |","ref":"resilience.html#load-shedding"},{"type":"extras","title":"Execution Pipeline - Resilience","doc":"The full resilience pipeline for each job:\n\n```\n1. Load shedding check (system-level)\n2. Rate limit check (per-worker)\n3. Bulkhead check (per-worker concurrency)\n4. Circuit breaker check (per-worker health)\n5. Global middleware chain\n6. Worker middleware chain\n7. Worker:perform/1\n```\n\nAny check that fails results in a **snooze** — the job is rescheduled without\ncounting as a failure attempt.","ref":"resilience.html#execution-pipeline"},{"type":"extras","title":"Unique Jobs","doc":"# Unique Jobs\n\nShigoto can deduplicate jobs so that enqueuing \"the same\" job twice does not\ncreate two rows. Uniqueness is **opt-in** and scoped: it is defined by which job\nfields make up the key, which job states count, and an optional time window.\n\nA plain `insert` with no unique options **never** deduplicates. Two identical\n`insert` calls produce two independent jobs. Deduplication only happens when you\neither pass a `unique` option or the worker exports a `unique/0` callback.","ref":"uniqueness.html"},{"type":"extras","title":"Configuring Uniqueness - Unique Jobs","doc":"Provide a `unique` map, either per-insert or as a worker default via `unique/0`.\nAny keys you omit fall back to `?DEFAULT_UNIQUE` in `shigoto_repo`:\n\n```erlang\n#{\n    keys => [worker, args],\n    states => [available, executing, retryable],\n    period => infinity,\n    replace => [],\n    debounce => undefined\n}\n```\n\n- **keys** - which fields form the identity of the job. Supported: `worker`,\n  `args`, `queue`. The key is built by `build_unique_key/4`: the selected fields\n  are sorted, `args` is JSON-encoded, and the parts are joined with `:` into the\n  job's `unique_key` column.\n- **states** - a new insert only conflicts with an existing job whose `state` is\n  in this list. The default covers in-flight work (`available`, `executing`,\n  `retryable`) but **not** terminal states, so a `completed`, `discarded`, or\n  `cancelled` job never blocks a fresh enqueue.\n- **period** - `infinity` (match any existing job in the given states) or a\n  number of seconds. With a period, `find_existing_job/3` adds\n  `inserted_at >= now() - make_interval(secs => Period)`, so a job older than the\n  window no longer blocks a new one.\n- **replace** - a list of fields to overwrite on the existing job when a\n  conflict is found (`args`, `priority`, `max_attempts`, `scheduled_at`). Empty\n  means \"keep the existing job untouched\".\n- **debounce** - seconds; when set, a conflict pushes the existing job's\n  `scheduled_at` forward to `now() + debounce`, so a burst of enqueues keeps\n  sliding the run time later.\n\nA worker default:\n\n```erlang\n-module(sync_worker).\n-behaviour(shigoto_worker).\n-export([perform/1, unique/0]).\n\nperform(Args) -> do_sync(Args).\n\nunique() ->\n    #{keys => [worker, args], period => 300}.\n```\n\nWhen a conflict is detected, the insert returns `{ok, {conflict, Job}}` instead\nof `{ok, Job}`, so callers can tell a deduplicated enqueue from a fresh one.","ref":"uniqueness.html#configuring-uniqueness"},{"type":"extras","title":"How It Works - Unique Jobs","doc":"`insert_job/3` calls `resolve_unique/2`. If that returns `none` (no unique opts\nand no `unique/0` callback) it goes straight to `do_insert/4` - a plain insert\nwith no deduplication. Otherwise it calls `insert_unique/4`, which:\n\n1. Builds the `unique_key` with `build_unique_key/4`.\n2. Derives a lock key with `erlang:phash2(UniqueKey)`.\n3. Opens a `pgo:transaction/2` and takes a **Postgres advisory transaction\n   lock**: `SELECT pg_advisory_xact_lock($1)`. This serialises concurrent\n   inserts that hash to the same key; the lock is released automatically when\n   the transaction commits or rolls back.\n4. Calls `find_existing_job/3` to look for a matching job within the configured\n   `states` (and `period`, if set).\n5. If one exists, `maybe_replace/4` applies the `replace`/`debounce` policy and\n   returns `{ok, {conflict, Job}}`. If none exists, it does the real\n   `do_insert/4`.","ref":"uniqueness.html#how-it-works"},{"type":"extras","title":"Why an Advisory Lock, Not a UNIQUE Index - Unique Jobs","doc":"The obvious alternative - a `UNIQUE` index on `unique_key` - is too blunt for\nShigoto's semantics:\n\n- **Uniqueness is state-scoped.** A `completed` job may legitimately share a key\n  with a brand-new job you want to run again. A blanket UNIQUE index would reject\n  that second insert forever, even though the first job is long finished.\n- **Uniqueness is period-scoped.** With `period => 300`, a job from an hour ago\n  must not block a new one. A UNIQUE index has no notion of a time window; it\n  would keep colliding regardless of age.\n- **Replace/debounce need read-then-write.** Overwriting fields or sliding\n  `scheduled_at` on the existing job requires finding it first and then updating\n  it. A UNIQUE index only gives you insert-or-fail, not the conditional\n  find-and-update this policy needs.\n\nThe advisory transaction lock gives exactly the guarantee that is needed and no\nmore: it prevents two concurrent transactions from both seeing \"no existing job\"\nand both inserting, while leaving the actual \"is this a duplicate?\" decision to a\nnormal scoped query that respects states and period. It locks a hash of the key\nrather than a real row, so it costs nothing when there is no contention and never\nleaves a constraint behind that would wrongly block a legitimate future job.","ref":"uniqueness.html#why-an-advisory-lock-not-a-unique-index"},{"type":"extras","title":"Encryption","doc":"# Encryption\n\nShigoto supports AES-256-GCM encryption for job args at rest. When configured,\njob arguments are encrypted before writing to PostgreSQL and decrypted\ntransparently when claimed. Workers always receive plaintext args.","ref":"encryption.html"},{"type":"extras","title":"Configuration - Encryption","doc":"Set a 32-byte encryption key in `sys.config`:\n\n```erlang\n{shigoto, [\n    {pool, my_app_db},\n    {encryption_key, <<\n        16#a1, 16","ref":"encryption.html#configuration"},{"type":"extras","title":"b2, 16#c3, 16#d4, 16#e5, 16#f6, 16#07, 16#18, - Encryption","doc":"16#29, 16#3a, 16#4b, 16#5c, 16#6d, 16#7e, 16#8f, 16#90,\n        16#a1, 16#b2, 16#c3, 16#d4, 16#e5, 16#f6, 16#07, 16#18,\n        16#29, 16#3a, 16#4b, 16#5c, 16#6d, 16#7e, 16#8f, 16#90\n    >>}\n]}.\n```\n\nOr generate a key at runtime:\n\n```erlang\nKey = crypto:strong_rand_bytes(32),\napplication:set_env(shigoto, encryption_key, Key).\n```","ref":"encryption.html#b2-16-c3-16-d4-16-e5-16-f6-16-07-16-18"},{"type":"extras","title":"How It Works - Encryption","doc":"1. On `insert/1`: args are JSON-encoded, then encrypted with AES-256-GCM\n   using a random 12-byte IV. The ciphertext, IV, and auth tag are stored\n   as a single binary in the `args` column.\n2. On `claim_jobs/3`: the encrypted args are decrypted and returned as\n   the original JSON binary.\n3. Workers call `perform/1` with the original plaintext map — no decryption\n   needed in worker code.","ref":"encryption.html#how-it-works"},{"type":"extras","title":"Key Rotation - Encryption","doc":"For periodic key rotation, use `encryption_keys` (a list, newest first):\n\n```erlang\n{shigoto, [\n    {pool, my_app_db},\n    {encryption_keys, [\n        NewKey,   %% Used for new encryptions\n        OldKey    %% Still used for decryption of existing jobs\n    ]}\n]}.\n```\n\nWhen a job is claimed, shigoto tries decryption with each key in order.\nIf the current key fails, it falls back to older keys. On successful\ndecryption with an older key, the args are re-encrypted with the newest\nkey on the next write.","ref":"encryption.html#key-rotation"},{"type":"extras","title":"What's Encrypted - Encryption","doc":"- Job `args` — the arguments map passed to workers\n- The `meta` field is **not** encrypted (it's used for internal tracking)","ref":"encryption.html#what-s-encrypted"},{"type":"extras","title":"Without Encryption - Encryption","doc":"If no encryption key is configured, args are stored as plaintext JSON.\nThis is the default. You can enable encryption at any time — new jobs\nwill be encrypted, existing plaintext jobs continue to work.","ref":"encryption.html#without-encryption"},{"type":"extras","title":"Telemetry","doc":"# Telemetry\n\nShigoto emits [telemetry](https://github.com/beam-telemetry/telemetry) events\nacross the job lifecycle, queue operations, resilience decisions, batches, and\ncron scheduling. Every event is a stable contract: attach a handler to any event\nname below and forward the measurements to a metrics reporter\n(`telemetry_metrics`, Prometheus, StatsD, ...) or your logging pipeline.\n\nAll events are emitted via `telemetry:execute/3` from `shigoto_telemetry`.","ref":"telemetry.html"},{"type":"extras","title":"Event Reference - Telemetry","doc":"Measurement units:\n\n- `count` is always `1` (increment a counter/sum).\n- `duration` is in **native** time units (`erlang:monotonic_time/0` deltas).\n- `duration_ms`, `queue_wait_ms`, `retry_after_ms` are **milliseconds**.\n- `progress` is a **percentage** (`0..100`).\n- `claimed` is a **job count** (jobs claimed by that poll).\n\nEvery event also carries `domain => [shigoto]` in its metadata (used by the OTP\nlogger for filtering); it is omitted from the tables below for brevity.","ref":"telemetry.html#event-reference"},{"type":"extras","title":"Job Events - Telemetry","doc":"| Event | Measurements | Metadata |\n|-------|-------------|----------|\n| `[shigoto, job, inserted]` | `count` | job_id, worker, queue, attempt, priority |\n| `[shigoto, job, claimed]` | `count, queue_wait_ms` | job_id, worker, queue, attempt, priority |\n| `[shigoto, job, completed]` | `count, duration, duration_ms, queue_wait_ms` | job_id, worker, queue, attempt, priority |\n| `[shigoto, job, failed]` | `count, duration, duration_ms, queue_wait_ms` | job_id, worker, queue, attempt, priority, reason |\n| `[shigoto, job, snoozed]` | `count` | job_id, worker, queue, attempt, priority, snooze_reason |\n| `[shigoto, job, discarded]` | `count` | job_id, worker, queue, attempt, priority |\n| `[shigoto, job, cancelled]` | `count` | job_id, worker, queue, attempt, priority |\n| `[shigoto, job, progress]` | `progress` | job_id, worker, queue, attempt, priority, progress |","ref":"telemetry.html#job-events"},{"type":"extras","title":"Queue Events - Telemetry","doc":"| Event | Measurements | Metadata |\n|-------|-------------|----------|\n| `[shigoto, queue, poll]` | `count, claimed` | queue |\n| `[shigoto, queue, paused]` | `count` | queue |\n| `[shigoto, queue, resumed]` | `count` | queue |","ref":"telemetry.html#queue-events"},{"type":"extras","title":"Resilience Events - Telemetry","doc":"| Event | Measurements | Metadata |\n|-------|-------------|----------|\n| `[shigoto, resilience, rate_limited]` | `count, retry_after_ms` | worker |\n| `[shigoto, resilience, circuit_open]` | `count` | worker |\n| `[shigoto, resilience, bulkhead_full]` | `count` | worker |\n| `[shigoto, resilience, load_shed]` | `count` | priority |","ref":"telemetry.html#resilience-events"},{"type":"extras","title":"Batch Events - Telemetry","doc":"| Event | Measurements | Metadata |\n|-------|-------------|----------|\n| `[shigoto, batch, completed]` | `count` | batch_id, total_jobs, completed_jobs, discarded_jobs |","ref":"telemetry.html#batch-events"},{"type":"extras","title":"Cron Events - Telemetry","doc":"| Event | Measurements | Metadata |\n|-------|-------------|----------|\n| `[shigoto, cron, scheduled]` | `count` | name, worker, schedule |","ref":"telemetry.html#cron-events"},{"type":"extras","title":"Testing Events - Telemetry","doc":"| Event | Measurements | Metadata |\n|-------|-------------|----------|\n| `[shigoto, testing, mode_armed]` | `count` | mode |\n\nEmitted once at boot when a non-production `testing` mode (`inline`/`manual`) is\narmed. Treat its presence in a production metrics stream as a red flag: inserts\nare not persisting. See `shigoto_config:testing_mode/0`.","ref":"telemetry.html#testing-events"},{"type":"extras","title":"Attaching a Raw Handler - Telemetry","doc":"The lowest-level integration is a plain `telemetry` handler:\n\n```erlang\ntelemetry:attach_many(\n    ~\"shigoto-logger\",\n    [\n        [shigoto, job, completed],\n        [shigoto, job, failed]\n    ],\n    fun(Event, Measurements, Metadata, _Config) ->\n        logger:info(~\"shigoto event\", #{\n            event => Event,\n            measurements => Measurements,\n            metadata => Metadata\n        })\n    end,\n    undefined\n).\n```","ref":"telemetry.html#attaching-a-raw-handler"},{"type":"extras","title":"Turning Events into Metrics - Telemetry","doc":"The example below wires the events into\n[`telemetry_metrics`](https://hexdocs.pm/telemetry_metrics/) definitions. It is\nillustration only; `telemetry_metrics` is **not** a dependency of Shigoto, so add\nit to your own application if you want it.\n\n```erlang\nmetrics() ->\n    [\n        %% Counters (each event carries count => 1)\n        telemetry_metrics:counter(~\"shigoto.job.completed.count\"),\n        telemetry_metrics:counter(~\"shigoto.job.failed.count\"),\n        telemetry_metrics:counter(~\"shigoto.job.discarded.count\"),\n\n        %% Job execution time, tagged by worker + queue\n        telemetry_metrics:distribution(\n            ~\"shigoto.job.completed.duration_ms\",\n            #{tags => [worker, queue]}\n        ),\n\n        %% Time a job waited in the queue before being claimed\n        telemetry_metrics:distribution(\n            ~\"shigoto.job.claimed.queue_wait_ms\",\n            #{tags => [queue]}\n        ),\n\n        %% Resilience signals, tagged by worker\n        telemetry_metrics:counter(\n            ~\"shigoto.resilience.circuit_open.count\",\n            #{tags => [worker]}\n        ),\n        telemetry_metrics:counter(\n            ~\"shigoto.resilience.rate_limited.count\",\n            #{tags => [worker]}\n        ),\n\n        %% Queue throughput: sum of jobs claimed per poll\n        telemetry_metrics:sum(~\"shigoto.queue.poll.claimed\", #{tags => [queue]})\n    ].\n```\n\nHand `metrics/0` to a reporter such as `telemetry_metrics_prometheus` to expose\nthe values, or `telemetry_metrics_statsd` to push them.\n\nThe equivalent in Elixir:\n\n```elixir\nimport Telemetry.Metrics\n\ndef metrics do\n  [\n    counter(\"shigoto.job.completed.count\"),\n    counter(\"shigoto.job.failed.count\"),\n    distribution(\"shigoto.job.completed.duration_ms\", tags: [:worker, :queue]),\n    distribution(\"shigoto.job.claimed.queue_wait_ms\", tags: [:queue]),\n    counter(\"shigoto.resilience.circuit_open.count\", tags: [:worker]),\n    sum(\"shigoto.queue.poll.claimed\", tags: [:queue])\n  ]\nend\n```","ref":"telemetry.html#turning-events-into-metrics"},{"type":"extras","title":"Testing","doc":"# Testing\n\nShigoto provides helpers for testing workers and job workflows without\nrunning background queue processes. The `perform_job/2,3` runner and the\n`inline`/`manual` testing modes need **no database at all**; `drain_queue/1`\nruns against a real pool for integration tests.","ref":"testing.html"},{"type":"extras","title":"perform_job — run a worker with no database - Testing","doc":"`shigoto:perform_job/2,3` runs a worker through the same perform path production\nuses (the middleware chain and `deps_results` injection) and returns the raw\nworker result. No database, no queue, no retry, and no resilience gating (rate\nlimits, circuit breakers, concurrency caps are skipped). It is a pure in-process\nunit-test runner.\n\n```erlang\nok = shigoto:perform_job(email_worker, #{~\"to\" => ~\"user@test.com\"}),\n\n{ok, #{~\"produced\" := 42}} =\n    shigoto:perform_job(sum_worker, #{~\"action\" => ~\"produce\", ~\"value\" => 42}),\n\n{error, _} = shigoto:perform_job(flaky_worker, #{~\"action\" => ~\"fail\"}).\n```\n\nPass predecessors' results (exactly as a real dependent would receive them) via\n`deps_results` in the third-argument options:\n\n```erlang\n{ok, _} = shigoto:perform_job(\n    rollup_worker, #{~\"action\" => ~\"consume\"},\n    #{deps_results => #{41 => #{~\"n\" => 7}}}\n).\n```\n\nOther options: `attempt`, `max_attempts`, `queue`, `id`, `meta`, `tags`,\n`priority`, `timeout`.","ref":"testing.html#perform_job-run-a-worker-with-no-database"},{"type":"extras","title":"Testing modes and enqueue assertions - Testing","doc":"Arm a testing mode so `insert/1,2` and `insert_all/1,2` stop persisting. Because\nthese modes change persistence, arming them requires **two** keys — a mode value\nthat leaks into production without the confirmation key falls back to the real\npersisted path and logs an error, so it can never silently drop jobs:\n\n```erlang\napplication:set_env(shigoto, testing, manual),\napplication:set_env(shigoto, testing_confirm_no_persistence, true).\n```\n\n- `manual` captures inserted jobs in a **process-local** buffer without running\n  or persisting them.\n- `inline` runs each inserted job synchronously and keeps no row; a job that\n  returns `{error, _}` raises `{shigoto_inline_job_failed, Worker, Reason}`.\n\nAssert on what your code enqueued with `m:shigoto_testing`:\n\n```erlang\nenqueue_signup_jobs(User),\nshigoto_testing:assert_enqueued(#{worker => welcome_email_worker}),\nshigoto_testing:assert_enqueued(#{args => #{~\"user_id\" => 5}}),\nshigoto_testing:refute_enqueued(#{queue => ~\"sms\"}),\n[_ | _] = shigoto_testing:all_enqueued().\n```\n\nFilters: `worker`, `queue`, `args` (containment), `tags` (containment), `state`.\nCall `shigoto_testing:reset/0` in `init_per_testcase` to clear the buffer.\n\n`manual` capture is per-process — it sees enqueues made by the calling process,\nnot by other processes it spawns. For cross-process expectations, use a real test\npool: outside `manual` mode the assertions query the pool via `find_jobs`, so the\nsame assertions work against a live database.\n\nNote: `batch`, `depends_on`, and `unique` are no-ops under `inline`/`manual`\n(shigoto logs a warning). Exercise those against a real pool with `drain_queue/1`.","ref":"testing.html#testing-modes-and-enqueue-assertions"},{"type":"extras","title":"drain_queue - Testing","doc":"The primary testing tool is `shigoto:drain_queue/1`, which synchronously\nclaims and executes all available jobs in a queue:\n\n```erlang\n-include_lib(\"stdlib/include/assert.hrl\").\n\nmy_test(_Config) ->\n    %% Insert a job\n    shigoto:insert(#{\n        worker => my_email_worker,\n        args => #{<<\"to\">> => <<\"test@example.com\">>}\n    }),\n\n    %% Execute all jobs synchronously\n    ok = shigoto:drain_queue(<<\"default\">>),\n\n    %% Assert the side effect happened\n    ?assert(email_was_sent(<<\"test@example.com\">>)).\n```\n\nWith a timeout:\n\n```erlang\nok = shigoto:drain_queue(<<\"emails\">>, #{timeout => 10000}).\n```","ref":"testing.html#drain_queue"},{"type":"extras","title":"Test Setup - Testing","doc":"A typical CT suite for shigoto tests:\n\n```erlang\n-module(my_jobs_SUITE).\n-behaviour(ct_suite).\n-include_lib(\"stdlib/include/assert.hrl\").\n\n-export([all/0, init_per_suite/1, end_per_suite/1,\n         init_per_testcase/2, end_per_testcase/2]).\n-export([test_email_job/1]).\n\n-define(POOL, my_test_pool).\n\nall() -> [test_email_job].\n\ninit_per_suite(Config) ->\n    {ok, _} = application:ensure_all_started(pgo),\n    {ok, _} = pgo:start_pool(?POOL, #{\n        host => \"localhost\",\n        port => 5432,\n        database => \"my_app_test\",\n        user => \"postgres\",\n        password => \"postgres\",\n        pool_size => 5\n    }),\n    application:set_env(shigoto, pool, ?POOL),\n    ok = shigoto_migration:up(?POOL),\n    Config.\n\nend_per_suite(_Config) ->\n    ok.\n\ninit_per_testcase(_TestCase, Config) ->\n    Config.\n\nend_per_testcase(_TestCase, _Config) ->\n    pgo:query(<<\"DELETE FROM shigoto_jobs\">>, [], #{pool => ?POOL}),\n    ok.\n\ntest_email_job(_Config) ->\n    {ok, Job} = shigoto:insert(#{\n        worker => my_email_worker,\n        args => #{<<\"to\">> => <<\"user@test.com\">>}\n    }),\n    ?assertEqual(<<\"available\">>, maps:get(state, Job)),\n    ok = shigoto:drain_queue(<<\"default\">>).\n```","ref":"testing.html#test-setup"},{"type":"extras","title":"Testing Workers Directly - Testing","doc":"For unit testing worker logic without the job queue:\n\n```erlang\ntest_worker_logic(_Config) ->\n    Args = #{<<\"to\">> => <<\"test@example.com\">>, <<\"subject\">> => <<\"Test\">>},\n    ?assertEqual(ok, my_email_worker:perform(Args)).\n```","ref":"testing.html#testing-workers-directly"},{"type":"extras","title":"Testing with Dependencies - Testing","doc":"```erlang\ntest_pipeline(_Config) ->\n    {ok, Step1} = shigoto:insert(#{\n        worker => extract_worker, args => #{}\n    }),\n    {ok, _Step2} = shigoto:insert(#{\n        worker => transform_worker, args => #{},\n        depends_on => [maps:get(id, Step1)]\n    }),\n    %% First drain executes Step1\n    ok = shigoto:drain_queue(<<\"default\">>),\n    %% Second drain executes Step2 (deps resolved)\n    ok = shigoto:drain_queue(<<\"default\">>).\n```","ref":"testing.html#testing-with-dependencies"},{"type":"extras","title":"Testing Batches - Testing","doc":"```erlang\ntest_batch_completion(_Config) ->\n    {ok, Batch} = shigoto:new_batch(#{\n        callback_worker => my_callback,\n        callback_args => #{<<\"report\">> => 1}\n    }),\n    BatchId = maps:get(id, Batch),\n    shigoto:insert(#{worker => my_worker, args => #{}, batch => BatchId}),\n    shigoto:insert(#{worker => my_worker, args => #{}, batch => BatchId}),\n\n    %% Drain executes both jobs + the callback\n    ok = shigoto:drain_queue(<<\"default\">>),\n\n    {ok, Final} = shigoto:get_batch(BatchId),\n    ?assertEqual(<<\"finished\">>, maps:get(state, Final)).\n```","ref":"testing.html#testing-batches"},{"type":"extras","title":"Testing Unique Jobs - Testing","doc":"```erlang\ntest_unique_prevents_duplicate(_Config) ->\n    Opts = #{unique => #{keys => [worker, args]}},\n    {ok, Job1} = shigoto:insert(\n        #{worker => my_worker, args => #{<<\"x\">> => 1}}, Opts\n    ),\n    {ok, {conflict, Job2}} = shigoto:insert(\n        #{worker => my_worker, args => #{<<\"x\">> => 1}}, Opts\n    ),\n    ?assertEqual(maps:get(id, Job1), maps:get(id, Job2)).\n```","ref":"testing.html#testing-unique-jobs"},{"type":"extras","title":"Docker Compose for Tests - Testing","doc":"Use Docker Compose for PostgreSQL in CI and local testing:\n\n```yaml\n# docker-compose.yml\nservices:\n  postgres:\n    image: postgres:17\n    environment:\n      POSTGRES_USER: postgres\n      POSTGRES_PASSWORD: root\n      POSTGRES_DB: shigoto_test\n    ports:\n      - \"5556:5432\"\n```","ref":"testing.html#docker-compose-for-tests"}],"proglang":"erlang","content_type":"text/markdown","producer":{"name":"ex_doc","version":"0.40.3"}}